// Üretilen dosya: tool/ozgun/uret.py. Sınav Hazırlık · TYT Türkçe: sözcükte ve cümlede anlam (her soru kendi cümlesini içerir) (orta).
const ozExam1Orta = <(String, String, List<String>, String)>[
  ('"Kuru" sözcüğü aşağıdakilerin hangisinde ilk anlamıyla kullanılmıştır?', 'Yağmurdan sonra kuru bir yer bulup oturduk.', ['Kuru gürültüden başka bir şey yapmadı.', 'Akşam yemeğinde pilavın yanına kuru fasulye pişirdik.', 'Konuşması çok kuru ve sıkıcıydı.'], 'İlk anlamıyla "kuru", nemi ya da ıslaklığı olmayan demektir; yağmur sonrası ıslak olmayan yer bu anlamdır. Kuru fasulyede kurutulmuş bir yiyecek adı söz konusudur.'),
  ('"Sert" sözcüğü aşağıdakilerin hangisinde ötekilerden farklı olarak mecaz anlamda kullanılmıştır?', 'Öğretmen, ödevini yapmayan öğrenciye sert bir dille çıkıştı.', ['Bu ekmeğin kabuğu fırında fazla kaldığı için çok sert olmuş.', 'Sert zeminde uyumak bütün gece sırtını ve belini ağrıttı.', 'Ceviz, sert kabuğu yüzünden elde zor kırılıyordu.'], 'Sertlik dokunmayla algılanan bir niteliktir; "sert dil" kırıcı, katı söz anlamında mecazdır. Öteki üç cümlede dokunma ile algılanan katılık vardır.'),
  ('"Derin" sözcüğü aşağıdaki cümlelerin hangisinde mecaz anlamıyla kullanılmıştır?', 'Bu romanın derin bir felsefesi var.', ['Göl, kıyıya yakın yerlerde bile insanı korkutacak kadar derindi.', 'Kuyunun ne kadar derin olduğu taş atılınca anlaşıldı.', 'Derin bir çukur açıp fidanı içine dikkatle yerleştirdik.'], 'Felsefenin derinliği ölçülemez; burada "derin" üzerinde çok düşünülmüş, anlamı zengin demektir. Diğerlerinde yüzeyden uzaklık anlatılır.'),
  ('"Bu şehirde sokaklar gece yarısından sonra derin bir sessizliğe gömülür." cümlesinde "gömülmek" sözcüğü hangi anlamda kullanılmıştır?', 'Mecaz anlamda; bir duruma tümüyle girmek', ['Gerçek anlamda; toprağın altına konmak', 'Yan anlamda; bir nesnenin bölmesine yerleşmek', 'Terim anlamda; bir sanat dalına özgü kavram'], 'Sokaklar fiziksel olarak toprağa girmez; sessizliğin tamamen egemen olduğu anlatılır. Bu nedenle sözcük mecaz anlamdadır.'),
  ('Aşağıdaki cümlelerin hangisinde "açık" sözcüğü "anlaşılır, belirgin" anlamında kullanılmıştır?', 'Müdür, kuralları herkesin anlayacağı açık bir dille anlattı.', ['Pencere açık kalınca oda soğudu.', 'Bütçede büyük bir açık oluştu.', 'Gemi, açık denizde beklenmedik bir fırtınaya yakalandı ve rotasını değiştirdi.'], 'Dilin açık olması, anlaşılır olması demektir. Pencerede kapalı olmayan, bütçede eksik, denizde kıyıdan uzak anlamları vardır.'),
  ('"Yüz" sözcüğü aşağıdakilerin hangisinde "bir şeyin dışa bakan tarafı" anlamında kullanılmıştır?', 'Kumaşın yüzü parlak, astarı mattı.', ['Sabah kalkınca yüzünü soğuk suyla yıkadı.', 'Bu salona yüz kişi sığar.', 'Ona yüz verince işi şımarıklığa vardırdı.'], 'Kumaşın yüzü, dışa gelen tarafıdır. İkinci cümlede organ, üçüncüde sayı, dördüncüde "yüz vermek" deyimi vardır.'),
  ('Aşağıdaki cümlelerin hangisinde "tutmak" sözcüğü "bir sonucu ya da tutarı bulmak" anlamında kullanılmıştır?', 'Alışverişin tutarı iki yüz lirayı tuttu.', ['Düşmemek için korkuluğu sıkıca tuttu.', 'Bu ilaç bana hiç tutmadı.', 'Taksiyi kapıda bizi beklesin diye bütün gün için tuttuk.'], '"Tutarı iki yüz lirayı tuttu" ifadesinde bir hesabın belli bir miktara ulaşması anlatılır. Diğerlerinde elle kavramak, etki etmek ve kiralamak anlamları vardır.'),
  ('"Ben her gün bu yoldan geçerim ama bugün yol bana çok uzun geldi." cümlesinde "uzun gelmek" sözüyle anlatılmak istenen nedir?', 'Yolun her zamankinden daha yorucu ve bitmez görünmesi', ['Yolun ölçüldüğünde gerçekten daha uzun olması', 'Konuşanın bu yolu ilk kez kullanıyor olması', 'Yolun bir bölümünün onarım nedeniyle trafiğe kapanmış olması'], 'Yol aynı yoldur; değişen, konuşanın algısıdır. "Uzun gelmek" burada öznel bir yorgunluk ve sıkıntı duygusunu anlatır.'),
  ('"Kara" sözcüğü aşağıdakilerin hangisinde "uğursuz, kötü" anlamında kullanılmıştır?', 'O kara günleri hatırlamak bile istemiyorum.', ['Gemiden inince karaya ayak bastık.', 'Kara saçları omuzlarına dökülüyordu.', 'Tahtaya kara tebeşirle yazılan yazı uzaktan okunmaz.'], '"Kara gün" acılı, sıkıntılı zaman anlamında mecazdır. İkinci cümlede kara "toprak parçası", üçüncü ve dördüncüde renk anlamındadır.'),
  ('Aşağıdaki cümlelerin hangisinde "perde" sözcüğü tiyatroya özgü bir terim olarak yer almıştır?', 'Oyunun ikinci perdesinde başkahraman sahneye hiç çıkmıyor.', ['Güneş girmesin diye perdeyi kapattı.', 'Gözüne perde indiği için ameliyat oldu.', 'Aramızdaki utanç perdesi o konuşmadan sonra sonunda kalktı.'], 'Tiyatroda "perde", oyunun bölümlerinden her birini anlatan bir terimdir. Diğerleri gündelik ya da mecaz kullanımlardır.'),
  ('"Kök" sözcüğü hangi cümlede dil bilgisi terimi olarak kullanılmıştır?', '"Gözlük" sözcüğünün kökü "göz"dür.', ['Ağacın kökleri kaldırımı çatlatmış.', 'Bu sorunun kökü çok eskilere dayanıyor.', 'Matematikte dokuzun karekökü üçtür.'], 'Dil bilgisinde kök, bir sözcüğün anlamlı en küçük ve parçalanamayan bölümüdür. Karekök ise matematik terimidir ama soru dil bilgisini sormaktadır.'),
  ('Aşağıdaki cümlelerin hangisinde "kırılma" sözcüğü fizik terimi olarak kullanılmıştır?', 'Işık sudan havaya geçerken kırılmaya uğrar.', ['Vazonun kırılma sesi bütün evi inletti.', 'Onun bu sözüyle bende bir kırılma oldu.', 'Kemikteki kırılma, çekilen röntgen filminde açıkça görüldü.'], 'Fizikte kırılma, ışığın bir ortamdan ötekine geçerken doğrultu değiştirmesidir.'),
  ('Aşağıdaki cümlelerin hangisinde eş anlamlı iki sözcük birlikte kullanılmıştır?', 'Dedem bize her akşam eski zamanlardan, köhne günlerden söz ederdi.', ['Hızlı koşan değil, yavaş ama kararlı yürüyen kazanır.', 'Kışın soğuğu da yazın sıcağı da kalın taş duvarlı bu evde hiç hissedilmez.', 'Evin içi aydınlıktı ama dışarısı zifiri karanlıktı.'], '"Eski" ile "köhne" aynı anlamı taşır. Diğer cümlelerde hızlı-yavaş, soğuk-sıcak, aydınlık-karanlık gibi karşıt sözcükler vardır.'),
  ('"Ödülünü alırken yaptığı mütevazı konuşma salondakileri çok etkiledi." cümlesindeki "mütevazı" sözcüğünün eş anlamlısı hangisidir?', 'alçakgönüllü', ['gösterişe düşkün', 'heyecanlı', 'kısa'], '"Mütevazı", kendini başkalarından üstün görmeyen, alçakgönüllü demektir.'),
  ('Aşağıdaki cümlelerin hangisinde karşıt anlamlı sözcükler bir arada kullanılmıştır?', 'Başarıyı da başarısızlığı da aynı olgunlukla karşıladı.', ['Uzun ve yorucu bir yolculuktan sonra eve vardık.', 'Güzel, temiz ve her köşesi özenle bakılmış bir bahçesi vardı.', 'Hem çalışkan hem de dürüst bir öğrenciydi.'], 'Başarı ile başarısızlık karşıt kavramlardır. Diğer cümlelerde birbirini tamamlayan, aynı yöne işaret eden nitelemeler vardır.'),
  ('Aşağıdaki cümlelerin hangisinde sesteş (eş sesli) sözcükler bir arada kullanılmıştır?', 'Gül bahçesinde açan güllere bakıp gül, dedi annem.', ['Bahçedeki gül fidanlarını budadık.', 'Sevinçten gözleri ışıl ışıl parlıyordu, sesi titriyordu.', 'Ağaçların dalları rüzgârla eğiliyordu.'], 'İlk cümlede çiçek anlamındaki "gül" ile "gülmek" eyleminin emri olan "gül" birlikte kullanılmıştır; bunlar sesteştir.'),
  ('"Kar" ve "kâr" sözcükleriyle ilgili aşağıdaki yargılardan hangisi doğrudur?', 'Şapka, okunuş ve anlam farkını gösterdiği için ikisi farklı sözcüktür.', ['İkisi aynı sözcüğün yazım kılavuzlarına göre değişen iki farklı yazımıdır.', 'Şapkalı biçim yalnızca şiirde kullanılır.', '"Kâr", karın erimesiyle oluşan sudur.'], '"Kar" yağış, "kâr" ise kazanç anlamındadır. Şapka, a ünlüsünün ince okunuşunu gösterir ve iki sözcüğü birbirinden ayırır.'),
  ('Aşağıdaki cümlelerin hangisinde soyut anlamlı bir sözcük kullanılmamıştır?', 'Masanın üstündeki vazoyu pencerenin önüne taşıdı.', ['Çocukların neşesi bütün evi sardı.', 'Onun dürüstlüğüne herkes güvenirdi.', 'İçimdeki merak, onun gelişini beklerken bir türlü dinmiyordu.'], 'Masa, vazo ve pencere beş duyuyla algılanan somut varlıklardır. Diğer cümlelerde neşe, dürüstlük ve merak gibi soyut kavramlar vardır.'),
  ('"Ses" ve "koku" sözcükleriyle "düşünce" ve "hayal" sözcükleri arasındaki temel fark aşağıdakilerden hangisidir?', 'İlk ikisi duyularla algılanır, son ikisi algılanmaz.', ['İlk ikisi soyut, son ikisi somut anlamlıdır.', 'İlk ikisi eylem, son ikisi addır.', 'İlk ikisi yalnızca doğada, son ikisi yalnızca kentte bulunur.'], 'Ses işitme, koku koklama duyusuyla algılanır ve somuttur; düşünce ve hayal zihinsel kavramlar olduğundan soyuttur.'),
  ('Bir sözcüğün önceleri geniş bir kavramı karşılarken zamanla bu kavramın yalnızca bir türünü ya da bölümünü anlatır duruma gelmesi aşağıdakilerden hangisiyle adlandırılır?', 'Anlam daralması', ['Anlam genişlemesi', 'Sesteş sözcük oluşumu', 'Ad aktarması yoluyla adlandırma'], 'Kapsamı geniş bir anlamın daha dar ve belirli bir anlama sınırlanması anlam daralması olarak adlandırılır. Tersi, kapsamın büyümesidir ve anlam genişlemesi denir.'),
  ('"Mürekkep" önceleri yalnızca yazı yazılan sıvıyı anlatırken bugün yazıcı kartuşundaki boyayı da anlatmaktadır. Bu değişim nasıl adlandırılır?', 'Anlam genişlemesi', ['Anlam daralması', 'Ad aktarması', 'Güzel adlandırma yoluyla örtmece'], 'Sözcük eski anlamını korurken yeni varlıkları da karşılamaya başlamıştır; bu, kapsamın büyümesi yani anlam genişlemesidir.'),
  ('Aşağıdaki cümlelerin hangisinde ad aktarması (mecazımürsel) yapılmıştır?', 'Bu akşam Yunus Emre okuyacağız.', ['Yunus Emre, Anadolu\'da yaşamış bir halk ozanıdır.', 'Yunus Emre\'nin doğum yeri kesin olarak bilinmez.', 'Yunus Emre\'yi anlatan bir belgesel izledik.'], '"Yunus Emre okumak", şairin kendisi yerine şiirlerinin kastedilmesidir; söyleyenin adı söylenen yerine kullanılmıştır. Bu ad aktarmasıdır.'),
  ('"Ankara bu konuda henüz bir açıklama yapmadı." cümlesinde "Ankara" sözcüğüyle aşağıdakilerden hangisi kastedilmektedir?', 'Türkiye\'nin hükûmeti', ['Ankara\'da yaşayan bütün halk', 'Ankara Büyükşehir Belediyesi', 'Ankara\'daki gazeteciler'], 'Bir yerin adı, orada bulunan yönetimi anlatmak için kullanılmıştır. Bu, benzetme amacı gütmeyen bir ad aktarmasıdır.'),
  ('"Çocuk, bir bardak suyu bir dikişte içti." cümlesindeki ad aktarması hangi ilişkiye dayanır?', 'Kap ile içindeki', ['Parça ile bütün', 'Yazar ile eseri', 'Yer ile orada yaşayanlar'], 'İçilen bardak değil, bardağın içindeki sudur; kabın adı içindeki şey için kullanılmıştır.'),
  ('"Türkiye" yerine "Ay yıldızlı topraklar" denmesi aşağıdakilerden hangisine örnektir?', 'Dolaylama', ['Ad aktarması', 'Kişileştirme', 'Güzel adlandırma'], 'Bir varlığı tek sözcükle anmak yerine onu birkaç sözcükle dolaylı biçimde anlatmaya dolaylama denir.'),
  ('Söylenmesi hoş olmayan, korkulan ya da utanç verici bir şeyi asıl adıyla değil, daha yumuşak bir adla anma aşağıdakilerden hangisidir?', 'Güzel adlandırma', ['Dolaylama', 'Anlam genişlemesi', 'Duyular arası aktarma'], 'Korkulan ya da hoş karşılanmayan bir kavramı daha hoş bir sözle anmaya güzel adlandırma (örtmece) denir.'),
  ('"Mutfaktan tencere tava şangırtısı, salondan da çocukların cıvıltısı geliyordu." cümlesinde kaç tane ses yansımalı sözcük vardır?', 'İki', ['Bir', 'Üç', 'Dört'], '"Şangırtı" ve "cıvıltı" seslerin yansımasından türemiştir. Tencere, tava, mutfak ve salon yansıma sözcük değildir.'),
  ('"Fısıldamak" sözcüğü için aşağıdakilerden hangisi söylenebilir?', 'Bir sesin yansımasından türemiş bir eylemdir.', ['Bir nesnenin adı olan somut bir sözcüktür.', 'Yabancı dilden Türkçeye geçmiş, alana özgü bir terimdir.', 'Bir duyguyu anlatan soyut bir addır.'], '"Fısıl" yansımasından türeyen "fısıldamak", çok alçak sesle konuşmayı anlatan bir eylemdir.'),
  ('Aşağıdaki cümlelerin hangisinde ikileme "pekiştirme" değil, "yaklaşıklık" anlamı katmıştır?', 'Toplantıya beş on kişi geldi.', ['Yavaş yavaş yürüyerek eve vardı.', 'Masmavi gökyüzüne uzun uzun baktı.', 'Gece boyunca derin derin düşündü.'], '"Beş on" kesin olmayan, yaklaşık bir sayıyı anlatır. Diğerlerinde ikilemeler anlamı güçlendirir.'),
  ('"Çocuklar bahçede çığlık çığlığa koşuşturuyordu." cümlesindeki ikileme hangi göreviyle kullanılmıştır?', 'Eylemin nasıl yapıldığını belirtir.', ['Bir varlığın rengini bildirir.', 'Bir varlığın sayısını yaklaşık verir.', 'Eylemin yapıldığı yeri gösterir.'], '"Çığlık çığlığa" koşuşturmanın biçimini anlatır, yani durum bildirir.'),
  ('Aşağıdaki cümlelerin hangisinde birbirine karşıt anlamlı sözcüklerden oluşmuş bir ikileme vardır?', 'Er geç bu yanlışın farkına varacaksın.', ['Ufak tefek işleri hemen hallettik.', 'Eğri büğrü yollardan geçerek köye ulaştık.', 'Kırık dökük eşyaları bir kenara ayırdık.'], '"Er" erken, "geç" ise gecikmiş anlamındadır; karşıt sözcüklerden kurulmuş "er geç" ikilemesi "eninde sonunda" anlamı taşır.'),
  ('"Göz yummak" deyimi aşağıdaki cümlelerin hangisinde "görmezlikten gelmek" anlamında kullanılmıştır?', 'Öğretmen, küçük kusurlarına bu seferlik göz yumdu.', ['Yaşlı kadın huzur içinde gözlerini yumdu.', 'Güneş çok parlak olunca gözlerini yumdu.', 'Çocuk karanlıktan korktuğu için gözlerini sıkıca yumdu.'], 'Kusura göz yummak, onu bilerek görmezden gelmek demektir. Diğerlerinde göz kapaklarını kapamak (ya da ölmek) anlatılır.'),
  ('"Ağzında bakla ıslanmamak" deyimi aşağıdaki kişilerden hangisi için kullanılmaya en uygundur?', 'Duyduğu bir şeyi hemen başkalarına anlatan Selin', ['Yemeğini hiç bitirmeden kalkan Emre', 'Konuşmayı hiç sevmeyen, sessiz Burak', 'Her sözünü uzun uzun düşünerek söyleyen, ölçülü Ayşe'], 'Deyim, sır saklayamayan, öğrendiğini hemen söyleyen kişiler için kullanılır.'),
  ('"Dut yemiş bülbüle dönmek" deyimi aşağıdaki durumlardan hangisini anlatır?', 'Her zaman konuşkan birinin birden susup kalması', ['Birinin hiç beklenmedik bir anda yüksek sesle şarkı söylemeye başlaması', 'Bir kimsenin çok yemek yemesi', 'Birinin sevinçten havalara uçması'], 'Deyim, her zaman konuşan birinin sıkıntı ya da utanç yüzünden hiç konuşmaz olmasını anlatır.'),
  ('"Arkadaşının sınavı kazandığını duyunca ... ; tebrik etmek için hemen telefona sarıldı." cümlesinde boşluğa hangisi uygun düşer?', 'dünyalar onun oldu', ['burnu sürtüldü', 'içine kurt düştü', 'gözünü kan bürüdü, öfkelendi'], 'Arkadaşının başarısına sevinen biri için "dünyalar onun olmak" (çok sevinmek) uygundur. Diğerleri gurur kırılması, kuşku ve öfke bildirir.'),
  ('"Kendini hep haklı gören kardeşi, hatasını kabul etmek bir yana, bir de karşı çıktı." Bu cümlede anlatılan davranış hangi deyimle özetlenebilir?', 'Hem suçlu hem güçlü olmak', ['Ateşe atılmak', 'Kulağına küpe olmak', 'Ağzına bir parmak bal çalmak'], 'Hatalıyken üstelik karşı çıkan, haklıymış gibi davranan kişi için "hem suçlu hem güçlü" denir.'),
  ('"Kulak asmamak" deyimi aşağıdaki cümlelerin hangisinde doğru kullanılmıştır?', 'Annesinin uyarılarına kulak asmadı, yağmurda şemsiyesiz çıktı.', ['Kulak asmadığı için şarkıyı çok güzel dinledi.', 'Sesi çok hoşuna gitti, kulak astı ve uyudu.', 'Kulak asmayan çocuk, büyüklerinin her sözünü harfiyen yerine getirdi.'], '"Kulak asmamak" bir söze önem vermemek demektir; annesinin uyarısını dinlemeyip yağmurda şemsiyesiz çıkmak bu anlamla uyumludur.'),
  ('"Onca uğraştan sonra elde ettiği küçük kazancı bir gecede harcadı." cümlesindeki durumu en iyi anlatan deyim hangisidir?', 'Har vurup harman savurmak', ['Kemerleri sıkmak', 'Eli sıkı olmak', 'Ağzının tadını bilmek, iyi yemek'], '"Har vurup harman savurmak", parayı düşünmeden, çarçur ederek harcamaktır. Diğer seçenekler tutumluluğu anlatır.'),
  ('Aşağıdaki durumlardan hangisi "Sabreden derviş muradına ermiş." atasözüyle en iyi açıklanır?', 'Yıllarca başvuru yapan Deniz\'in sonunda istediği okula kabul edilmesi', ['Parasını çarçur eden Ece\'nin borca girmesi', 'Bir anlık öfkeyle en yakın arkadaşını kıran Cem\'in ertesi gün pişman olması', 'Sınavdan önce hiç çalışmayan Kaan\'ın başarısız olması'], 'Atasözü, sabırla bekleyip çaba gösterenin sonunda isteğine kavuşacağını anlatır; Deniz\'in durumu buna uyar.'),
  ('"Sütten ağzı yanan yoğurdu üfleyerek yer." atasözü anlamca aşağıdakilerden hangisine en yakındır?', 'Bir kez zarar gören, benzer durumlarda aşırı temkinli olur.', ['Sıcak yiyecekler soğutularak yenmelidir.', 'Bir işi yapmadan önce mutlaka deneyimli birine danışılmalıdır.', 'Yaşlıların sözü dinlenirse insan kolay kolay zarar görmez.'], 'Atasözü, kötü bir deneyimin insanı benzer durumlarda gereğinden fazla dikkatli yaptığını anlatır.'),
  ('"Mahallemizdeki fırıncı, kalitesiz un kullandığı için müşterilerini birer birer kaybetti; yıllarca süren emeği bir anda boşa gitti." Bu durumu en iyi özetleyen atasözü hangisidir?', 'Yalancının mumu yatsıya kadar yanar.', ['Ayağını yorganına göre uzat ki sonunda pişman olmayasın.', 'Dost acı söyler ama sonunda haklı çıkar.', 'Akıl akıldan üstündür, danışan dağı aşmış.'], 'Hileyle elde edilen kazancın kısa sürede ortaya çıkıp sona ereceğini anlatan "Yalancının mumu yatsıya kadar yanar" bu duruma uygundur.'),
  ('Atasözleriyle ilgili aşağıdaki yargılardan hangisi doğrudur?', 'Halkın uzun deneyimlerinden süzülmüş, kalıplaşmış öğütlerdir.', ['Her birinin yazarı bellidir ve kaynaklarda adıyla anılır.', 'Sözcüklerinin yeri değiştirilerek kolayca yeni biçimler kurulabilir.', 'Yalnızca gerçek anlamlı sözcüklerden oluşurlar.'], 'Atasözlerinin söyleyeni belli değildir, kalıplaşmıştır ve çoğunlukla mecaz anlam içerir; halkın ortak deneyiminin ürünüdür.'),
  ('"Keskin sirke küpüne zarar." atasözü hangi kişiye öğüt vermek için söylenebilir?', 'Sinirlenince kendi sağlığını bozan birine', ['Eşyalarını özenle saklamayan birine', 'Yemeklerine her seferinde gereğinden fazla sirke koyan birine', 'Başkalarına sürekli öğüt veren birine'], 'Atasözü, aşırı öfkenin önce öfkelenen kişinin kendisine zarar verdiğini anlatır.'),
  ('"Onun keskin bakışlarından herkes çekiniyordu." cümlesinde "keskin" sözcüğünün kullanımıyla ilgili hangisi doğrudur?', 'Dokunmayla ilgili bir sıfat, görmeyle ilgili bir varlığa aktarılmıştır.', ['Tatla ilgili bir sıfat, işitmeyle ilgili bir varlığa aktarılmıştır.', 'Sözcük, gerçek anlamıyla bir bıçağın ağzının inceliğini nitelemektedir.', 'Sözcük, bir sesin yansımasından türemiştir.'], '"Keskin" kesici araçlar için dokunma duyusuyla algılanan bir niteliktir; bakış ise görmeyle algılanır. Bu, duyular arası aktarmadır.'),
  ('Aşağıdaki cümlelerin hangisinde duyular arası aktarma yapılmıştır?', 'Ninemin tatlı sesi hâlâ kulaklarımda.', ['Ninem bize her akşam masal okurdu.', 'Ninemin evi köyün en yüksek yerindeydi.', 'Ninemin bahçesindeki ağaçlar meyveye durmuştu.'], 'Tat duyusuyla ilgili "tatlı" sözcüğü, işitme duyusuyla algılanan "ses"i nitelemiştir.'),
  ('"Yumuşak bir renkle boyanmış duvarlar odaya huzur veriyordu." cümlesinde hangi duyulara ait nitelikler arasında aktarma vardır?', 'Dokunma ile görme', ['Tat ile işitme', 'Koku ile dokunma', 'İşitme ile koku alma'], '"Yumuşak" dokunmayla algılanan bir niteliktir; renk ise görme duyusuyla algılanır.'),
  ('"Afiyet olsun" sözü ile "Ellerine sağlık" sözü arasındaki fark nedir?', 'İlki yemek yiyen kişiye, ikincisi yemeği hazırlayana söylenir.', ['İlki yemeği hazırlayana, ikincisi yemek yiyene söylenir.', 'İkisi de yalnızca bayramlarda söylenen sözlerdir.', 'İlki sabahları, ikincisi akşamları kullanılan bir selamlaşmadır.'], '"Afiyet olsun" yemeği yiyecek ya da yemiş kişiye iyi dilektir; "Ellerine sağlık" emeğe teşekkür olarak hazırlayana söylenir.'),
  ('"Gözün aydın!" sözü hangi durumda kullanılır?', 'Sevilen bir kişinin dönüşü ya da sevindirici bir haber üzerine', ['Göz hastalığından kurtulan birine doktorun verdiği öğüt olarak', 'Karanlık bir odaya ışık yakıldığında', 'Bir sınavdan düşük not alan birini teselli edip ona umut verirken'], '"Gözün aydın", beklenen bir kişinin gelmesi ya da sevindirici bir haber için kutlama sözüdür.'),
  ('"Bu yıl buğday tarlası iyi bir ürün verdi; köylünün yüzü güldü." cümlesinde "yüzü gülmek" sözüyle anlatılan nedir?', 'Sıkıntıdan kurtulup rahata ermek', ['Kahkahalarla gülmek ve herkesi güldürmek', 'Yüzünde gülümseme olan bir fotoğraf çektirmek', 'Başkalarının sıkıntısıyla alay etmek'], '"Yüzü gülmek", sevinmek, sıkıntılardan kurtulup mutlu olmak anlamında bir deyimdir; bol ürün köylüyü rahatlatmıştır.'),
  ('"Bağlamak" sözcüğü hangi cümlede "bir sonuca varmak, sonuçlandırmak" anlamında kullanılmıştır?', 'Konuşmacı sözlerini kısa bir öğütle bağladı.', ['Ayakkabısının bağcıklarını sıkıca bağladı.', 'Atını ağaca bağlayıp suya indi.', 'Yeni köprü, iki yakayı birbirine bağladı ve yol kısaldı.'], 'Sözleri bir öğütle bağlamak, konuşmayı onunla bitirmek, sonuçlandırmaktır.'),
  ('"Ödevlerini yetiştirmek için gece geç saatlere kadar oturdu." cümlesinde "oturmak" sözcüğü hangi anlamda kullanılmıştır?', 'Bir iş için uzun süre çalışmak', ['Bir yerde ev tutup yaşamak', 'Bir sandalyeye yerleşip dinlenmek', 'Bir giysinin bedene uygun gelmesi'], 'Ödev için geç saatlere kadar oturmak, o işle uğraşarak zaman geçirmek, çalışmaktır.'),
  ('"Bu konudaki görüşlerini açıkça ortaya koydu." cümlesindeki "açıkça ortaya koymak" sözünün anlamca en yakını hangisidir?', 'dobra dobra söylemek', ['üstü kapalı anlatmak', 'lafı dolandırmak', 'dilinin altında bir şey saklamak'], 'Görüşü açıkça ortaya koymak, onu dolaysız söylemektir; "dobra dobra söylemek" bu anlamı karşılar. Diğerleri dolaylı anlatımı bildirir.'),
  ('"Bu romanı okurken zamanın nasıl geçtiğini anlamadım." cümlesiyle anlatılmak istenen hangisidir?', 'Romanın okuru kendine bağladığı', ['Romanın çok kısa olduğu', 'Romanı okumanın uzun sürdüğü', 'Okurun saati kaybettiği ve geç kaldığı'], 'Zamanın nasıl geçtiğini fark etmemek, okunan kitabın sürükleyici olduğunu sezdirir.'),
  ('"Komşumuz emeklilik ikramiyesini oğlunun düğününe harcayarak ... bir iş yaptı." cümlesinde boşluğa getirilecek sözcüğün anlamca uygun olanı hangisidir? (Cümle, olumlu bir değerlendirme bildirmektedir.)', 'yerinde', ['gereksiz', 'ölçüsüz', 'boşuna'], 'Cümle olumlu bir değerlendirme yapıyor; "yerinde bir iş" uygun, isabetli bir iş demektir. Diğer seçenekler olumsuzdur.'),
  ('Bir trafik kazasıyla ilgili aşağıdaki cümlelerden hangisinde, sözcüklerden biri cümlenin geri kalanıyla anlamca çelişecek biçimde kullanılmıştır?', 'Kazayı ucuz atlatan sürücü maalesef hayatını kaybetti.', ['Sabahki kazada sürücü hafif yaralandı ve akşam taburcu edildi.', 'Kazada yaralanan sürücü kısa sürede iyileşti.', 'Sürücü, kazadan sonra ambulansla hastaneye götürüldü.'], '"Ucuz atlatmak" bir tehlikeyi az zararla geçiştirmek demektir; "hayatını kaybetti" ise ölümü bildirir. Bu iki söz birbiriyle çelişir.'),
  ('Aşağıdaki cümlelerin hangisinde "tezat" sözcüğü anlamına uygun kullanılmıştır?', 'Sözleriyle davranışları arasındaki tezat herkesin dikkatini çekti.', ['Bu iki arkadaş tezat görüşleri sayesinde hep aynı şeyi savundu.', 'Dersin sonunda konuyu tezat bir biçimde özetledi.', 'Ali ile Ayşe her konuda aynı görüşte olduklarından aralarında tezat vardı.'], '"Tezat", karşıtlık demektir. Sözlerle davranışlar arasındaki uyumsuzluğu anlatmak için uygun kullanılmıştır; diğerlerinde anlamla çelişen bağlamlar vardır.'),
  ('"Müzede sergilenen eserlerin çoğu, yüzyıllar önce yapılmış özgün parçalardı." cümlesinde "özgün" sözcüğü hangi anlamdadır?', 'Kopya olmayan, asıl', ['Yeni yapılmış, çağdaş', 'Çok pahalı, değerli', 'Kırık, eksik parçaları olan'], '"Özgün" burada başka bir şeyin taklidi olmayan, asıl olan anlamına gelir.'),
  ('"Sınava iyi hazırlanmak için her gün düzenli olarak deneme çözüyordu." cümlesinde eylemin hangi gerekçeyle yapıldığı belirtilmiştir?', 'Ulaşılmak istenen bir hedefle', ['Gerçekleşmiş bir olayın sonucu olarak', 'Bir koşulun yerine gelmesine bağlı olarak', 'Bir durumun başka bir durumla kıyaslanmasıyla'], 'Deneme çözmek, iyi hazırlanma amacına yöneliktir; "için" burada amaç bildirir. Bu, amaç-sonuç ilişkisidir.'),
  ('"Fidanlar susuzluktan kurumasın diye her akşam bahçeyi suladık." cümlesindeki "diye" sözcüğü hangi anlamı katmıştır?', 'Amaç', ['Neden', 'Koşul', 'Zaman'], 'Bahçeyi sulamanın hedefi, fidanların kurumamasıdır; "diye" burada amaç bildirir.'),
  ('"Sabah alarmı duymadığım için servisi kaçırdım." cümlesindeki anlam ilişkisi aşağıdakilerin hangisinde de vardır?', 'Yolda trafik sıkışınca toplantıya geç kaldık.', ['Toplantıya geç kalmamak için erken yola çıktık.', 'Trafik açık olursa toplantıya yetişiriz.', 'Bu yol, öteki yoldan daha az trafiklidir.'], 'Verilen cümlede bir olayın gerçekleşmiş nedeni bildiriliyor; "trafik sıkışınca geç kaldık" cümlesinde de aynı neden-sonuç ilişkisi vardır.'),
  ('"Kardeşim, odasını toplasın diye annem ona yeni bir kitaplık aldı." cümlesinde annenin kitaplık almasının amacı hangisidir?', 'Kardeşimin odasını düzenli tutmasını istemesi', ['Kardeşimin odasının zaten düzenli olması', 'Kitaplığın indirimde satılması', 'Kardeşimin kitap okumayı sevmemesi ve bunu herkese söylemesi'], '"Toplasın diye" ifadesi amaç bildirir; anne kitaplığı, kardeşin odasını toplaması hedefiyle almıştır.'),
  ('"Bir dil, ancak yaşayan insanlar tarafından konuşulursa canlı kalır." cümlesinde dilin canlılığı neye bağlanmıştır?', 'Konuşulmaya devam edilmesine', ['Yazılı kaynaklarının çok olmasına', 'Sözlüklerinin düzenli yenilenmesine', 'Okullarda yabancı dillerle birlikte öğretilmesine'], '"Ancak ... konuşulursa" kalıbı, dilin canlı kalmasını tek bir koşula, konuşulmaya bağlamaktadır.'),
  ('"Yazar, okurların ilgisini çekmek amacıyla romanına gizemli bir başlangıç yazdı." cümlesinden aşağıdakilerin hangisi çıkarılabilir?', 'Gizemli başlangıç, bilinçli bir tercih olarak yazılmıştır.', ['Okurlar romanın başlangıcını sevmemiştir.', 'Romanın başlangıcı yazarın elinde olmadan gizemli olmuştur.', 'Yazar, okurların ilgisini çekemediği için pişmandır.'], '"Amacıyla" sözü yazarın belli bir hedef doğrultusunda davrandığını, yani bu başlangıcı bilerek seçtiğini gösterir.'),
  ('Aşağıdaki cümlelerin hangisinde karşılaştırma yapılmamıştır?', 'Bu yaz tatilimizi Karadeniz\'in bir köyünde geçirdik.', ['Bu yaz geçen yazdan çok daha sıcak geçti.', 'Köydeki evimiz, şehirdeki apartman dairemizden çok daha ferahtır.', 'Kardeşi gibi o da müziğe çok meraklıdır.'], 'İlk cümlede yalnızca bir olay aktarılmıştır. Diğerlerinde "-dan daha" ve "gibi" ile iki varlık ya da zaman kıyaslanmıştır.'),
  ('"Bu mahallede yaşayanların çoğu da tıpkı bizim gibi kırsaldan göç etmişti." cümlesinde nasıl bir karşılaştırma yapılmıştır?', 'Benzerlik yönünden', ['Üstünlük yönünden', 'Zaman ya da süre yönünden', 'Karşıtlık yönünden'], '"Tıpkı ... gibi" ifadesi, mahallede yaşayanlarla konuşanın göç etme bakımından benzediğini anlatır.'),
  ('"Bu dağın zirvesi, bölgedeki öteki zirvelerden çok daha yüksektir." cümlesindeki "çok daha" sözünün katkısı nedir?', 'Karşılaştırmadaki farkın büyüklüğünü vurgular.', ['Dağın bölgedeki en alçak dağ olduğunu gösterir.', 'Karşılaştırmayı ortadan kaldırıp yargıyı kesinleştirir.', 'İki zirvenin aynı yükseklikte olduğunu anlatır.'], '"Daha" karşılaştırma yapar; "çok" ise aradaki farkın büyük olduğunu vurgular.'),
  ('"Kahvaltıda oldukça az şey yedi." cümlesinde "oldukça" sözcüğünün işlevi nedir?', 'Bir niteliğin derecesini belirlemek', ['Eylemin zamanını bildirmek', 'Eylemin yapıldığı yeri göstermek', 'İki varlığı nitelik bakımından birbiriyle kıyaslamak'], '"Oldukça", "az" sıfatının derecesini artırarak niteliğin ölçüsünü belirler.'),
  ('Aşağıdaki cümlelerin hangisinde nesnel bir yargı vardır?', 'Kızılırmak, tamamı Türkiye topraklarında bulunan en uzun akarsudur.', ['Karadeniz\'in en güzel kenti Rize\'dir.', 'Kızılırmak kıyısında gün batımı insanı büyüler.', 'Bu ülkenin en lezzetli yemekleri Gaziantep\'tedir.'], 'Kızılırmak\'ın tamamı Türkiye sınırları içinde kalan en uzun akarsu olduğu doğrulanabilir bir bilgidir. Diğerleri kişiden kişiye değişen değerlendirmelerdir.'),
  ('"Bu roman 1922 yılında yayımlanmış, üç bölümden oluşan bir eserdir; bence yazarın en etkileyici kitabıdır." cümlesi için hangisi söylenebilir?', 'Hem nesnel hem de öznel yargı içerir.', ['Yalnızca nesnel yargılardan oluşur.', 'Yalnızca öznel yargılardan oluşur.', 'Hiçbir yargı bildirmeyen, yanıt bekleyen bir soru cümlesidir.'], 'Yayın yılı ve bölüm sayısı kanıtlanabilir bilgilerdir (nesnel); "en etkileyici kitabı" ise kişisel bir değerlendirmedir (öznel).'),
  ('"Su, deniz seviyesinde 100 °C\'de kaynar." cümlesinin nesnel olmasının nedeni nedir?', 'Deneyle doğrulanabilen ve kişiye göre değişmeyen bir bilgi vermesi', ['Bilim insanlarının çoğunun bu yargıyı doğru bulup beğenmiş olması', 'Cümlede bir sayının geçmesi', 'Yazarın bu konuda kesin bir dil kullanması'], 'Nesnel yargılar, kanıtlanabilir ve herkes için aynı olan bilgiler içerir; sıcaklık ölçümle doğrulanabilir.'),
  ('"Kentin tarihî çarşısında yaklaşık iki yüz dükkân bulunuyor ve bunların çoğu el sanatları ürünleri satıyor." cümlesine aşağıdakilerden hangisi eklenirse cümle öznel bir nitelik kazanır?', 'Çarşıda gezmek, insana geçmişe yolculuk yapıyormuş duygusu veriyor.', ['Çarşı, 16. yüzyılda yapılmıştır.', 'Dükkânların bir bölümü kuyumcudur.', 'Çarşı her gün sabah dokuzda açılır, akşam yedide kapanır; pazarları ise kapalıdır.'], '"Geçmişe yolculuk duygusu" kişisel bir izlenimdir. Diğer ekler, yapım tarihi, dükkân türü ve çalışma saatleri gibi doğrulanabilir bilgilerdir.'),
  ('"Bu köprü, kentin iki yakasını birbirine bağlayan tek ulaşım yoludur." yargısı neden nesneldir?', 'Durum gözlemle doğrulanabilir.', ['Yazar köprüyü çok beğenmiştir.', 'Köprü çok eski bir yapıdır.', 'Cümle duygusal sözcükler içerir ve okuru etkiler.'], 'Bir yakadan ötekine başka bir ulaşım yolu olup olmadığı gözlemle kontrol edilebilir; bu, yargıyı nesnel kılar.'),
  ('Aşağıdaki cümlelerin hangisinde gerçekleşmesi kesin olmayan bir yargı vardır?', 'Ali yarın toplantıya gelemeyebilir.', ['Ali dün toplantıya geldi.', 'Ali her toplantıya zamanında gelir.', 'Ali bu toplantıya gelmeyeceğini bana dün açıkça söyledi.'], '"Gelemeyebilir" biçimindeki olasılık bildiren yapı, yargının kesin olmadığını gösterir.'),
  ('"Kapı kilitli, ışıklar da sönük; ev sahipleri tatile çıkmış olmalı." cümlesinde varılan yargı neye dayanmaktadır?', 'Gözlemlenen belirtilerden yapılan çıkarıma', ['Ev sahiplerinin kendi açıklamasına', 'Komşulardan alınan kesin bilgiye', 'Konuşanın geçmişte yaşadığı bir anıya ve pişmanlığına'], 'Kilitli kapı ve sönük ışıklar ipucudur; "-mış olmalı" yapısı bu ipuçlarından yapılan bir tahmini bildirir.'),
  ('"Diyelim ki bu yolculuğa çıkmadın; o zaman bu güzel insanlarla hiç tanışamayacaktın." cümlesinde nasıl bir anlatım vardır?', 'Gerçekleşmemiş bir durum varsayılarak sonucu düşünülmüştür.', ['Gerçekleşmiş bir olayın nedeni açıklanmıştır.', 'Bir kavramın tanımı yapılmıştır.', 'Bir kişiye öğüt verilmiş ve hemen yolculuğa çıkması istenmiştir.'], '"Diyelim ki" ifadesi bir varsayım kurar; olmayan bir durum kabul edilerek doğuracağı sonuç anlatılmıştır.'),
  ('"Sanki bu şehirde yıllardır yaşıyormuş gibi bütün sokakları biliyordu." cümlesinde "sanki ... gibi" yapısı hangi anlamı katmıştır?', 'Gerçekte olmayan bir durumu varmış gibi göstererek benzetme', ['Kesin bir bilgiyi doğrulama', 'Bir eylemin amacını belirtme', 'Bir koşulun gerçekleşmesini sabırla bekleme ve umut etme'], '"Sanki ... gibi", kişinin gerçekte orada yıllardır yaşamadığını ama öyleymiş izlenimi verdiğini anlatır.'),
  ('"Kardeşim artık sabahları erken kalkıyor." cümlesinde "artık" sözcüğü hangi örtülü anlamı sağlar?', 'Kardeşin eskiden erken kalkmadığını', ['Kardeşin her zaman erken kalktığını', 'Kardeşin hiç uyumadığını', 'Kardeşin erken kalkmaktan hoşlanmadığını'], '"Artık" bir değişimi anlatır; şimdi erken kalkıyorsa daha önce böyle olmadığı sezdirilir.'),
  ('"Bu kez sınava zamanında geldi." cümlesinden aşağıdakilerden hangisi çıkarılabilir?', 'Daha önce en az bir sınava geç kaldığı', ['Her sınava zamanında geldiği', 'Sınavdan beklediğinden çok daha yüksek not aldığı', 'Sınavın ertelendiği'], '"Bu kez" sözü, önceki durumlarda bunun gerçekleşmediğini, yani geç kalındığını sezdirir.'),
  ('"Sen de mi bu filmi beğenmedin?" sorusunu soran kişi hakkında hangisi söylenebilir?', 'Filmi beğenmeyen başka kişiler olduğunu bilmektedir.', ['Filmi çok beğenmiş ve herkese önermiştir.', 'Filmi henüz izlememiştir ama yorumları okumuştur.', 'Filmin yönetmenini tanımaktadır.'], '"Sen de mi" sorusu, filmi beğenmeyenlerin yalnızca karşısındaki kişi olmadığını örtülü olarak bildirir.'),
  ('Aşağıdaki cümlelerin hangisinde ön yargılı bir tutum vardır?', 'Yeni gelen öğrenci gözlüklü olduğuna göre kesin çok çalışkandır.', ['Yeni gelen öğrencinin notlarını görünce çalışkan olduğunu anladım.', 'Yeni gelen öğrenciyle birkaç gün geçirdikten sonra onu tanıdım.', 'Yeni gelen öğrencinin karnesinde bütün dersleri pekiydi.'], 'Gözlük takmakla çalışkanlık arasında bir bağ yoktur; kişi tanınmadan dış görünüşüne göre hüküm verilmiştir.'),
  ('"Bu yazarın kitaplarını okumadım ama çok sıkıcı olduklarından eminim." cümlesinin ön yargı içermesinin nedeni nedir?', 'Bilmeden kesin bir hüküm verilmesi', ['Yazarın kitaplarının gerçekten sıkıcı olması', 'Cümlede karşılaştırma yapılması', 'Konuşanın yazarın kitaplarını okuyup beğenmemesi'], 'Ön yargı, bir şeyi tanımadan, denemeden hakkında olumlu ya da olumsuz kesin yargıya varmaktır; konuşan okumadığı kitapları yargılamaktadır.'),
  ('"Hiç tanımadığı halde komşusunun yeni kiracısına, şehirli olduğu için kibirli biri gözüyle bakıyordu." Bu cümlede eleştirilen davranış hangisidir?', 'İnsanları tanımadan genellemelerle yargılamak', ['Komşularla hiç ilgilenmemek ve onlara selam bile vermemek', 'Kiracılardan yüksek kira istemek', 'Şehirden köye taşınmak'], 'Kiracının şehirli olması, onu tanımadan "kibirli" diye nitelemek için gerekçe yapılmıştır; bu ön yargılı bir genellemedir.'),
  ('Aşağıdaki cümlelerin hangisinde bir esere yönelik olumlu eleştiri vardır?', 'Şair, sade bir dille derin duyguları anlatmayı başarmış.', ['Şiirlerdeki ağır dil, okuru eserden uzaklaştırıyor.', 'Kitaptaki şiirlerin çoğu birbirinin tekrarı gibi.', 'Şair, ilk kitabından sonra hiçbir biçimde gelişme gösterememiş.'], 'Sade dille derin duyguları anlatmayı başarmak övgüdür; diğerleri eserin kusurlarını dile getirir.'),
  ('"Film, görsel açıdan etkileyici olsa da senaryosu bir o kadar zayıf." cümlesi için hangisi söylenebilir?', 'Eserin hem olumlu hem olumsuz yönüne değinilmiştir.', ['Eser yalnızca övülmüştür.', 'Eser yalnızca yerilmiştir.', 'Eser hakkında yalnızca ölçülebilir, doğrulanabilir bilgiler verilmiştir.'], 'Görsellik övülmüş, senaryo ise zayıf bulunmuştur; cümle iki yönlü bir değerlendirme içerir.'),
  ('Aşağıdaki cümlelerin hangisinde pişmanlık anlamı, "keşke" sözcüğü kullanılmadan verilmiştir?', 'O sözleri söylediğim için kendimi hâlâ affedemiyorum.', ['Keşke o sözleri hiç söylemeseydim.', 'Keşke o gün evde kalsaydım.', 'Keşke o gün biraz daha sabırlı olsaydım, her şey farklı olurdu.'], 'İlk cümlede "kendimi hâlâ affedemiyorum" ifadesiyle pişmanlık dile getirilmiştir; diğerlerinde "keşke" ile kurulmuştur.'),
  ('Aşağıdaki cümlelerin hangisinde abartmaya başvurulmuştur?', 'Seni beklerken burada kök saldım.', ['Seni yarım saattir burada bekliyorum.', 'Seni beklerken iki bardak çay içtim.', 'Gelmeni beklerken bir yandan kitap okudum.'], '"Kök salmak", çok uzun süre beklemeyi abartılı biçimde anlatır; diğerleri olağan durumları aktarır.'),
  ('"Sesi o kadar gürdü ki bütün mahalle yerinden sıçradı." cümlesinde abartmanın amacı nedir?', 'Sesin çok yüksek olduğunu etkili biçimde anlatmak', ['Mahallede bir deprem olduğunu bildirmek', 'Mahallelinin küçük seslerden bile korkan insanlar olduğunu eleştirmek', 'Sesin kime ait olduğunu açıklamak'], 'Bütün mahallenin yerinden sıçraması, sesin gürlüğünü vurgulamak için yapılmış bir abartmadır.'),
  ('"Bu dağın tepesine çıkmak için bin bir zahmet çektik." cümlesindeki "bin bir" sözünün işlevi hangisidir?', 'Sayıyı değil, çokluğu abartarak anlatmak', ['Tam olarak bin bir zorlukla karşılaşıldığını bildirmek', 'Çekilen zahmetin az olduğunu vurgulamak', 'Dağın yüksekliğini metre olarak belirtmek'], '"Bin bir" kalıplaşmış bir abartmadır; tam bir sayı değil, çok sayıda zorluk anlatılır.'),
  ('"Bütün gün bilgisayar başında oturuyorsun; biraz da dışarı çıkıp hava alsan sağlığın için iyi olur." cümlesinde hangi iki anlam bir aradadır?', 'Eleştiri ve öneri', ['Övgü ve teşekkür', 'Pişmanlık ve geleceğe dair umut', 'Tahmin ve tanım'], 'Bütün gün bilgisayar başında oturmak eleştirilmiş, ardından dışarı çıkıp hava alması önerilmiştir.'),
  ('"Ah, gençliğimde şu dili öğrenseydim, şimdi bu kadar zorlanmazdım." cümlesine yakın anlamlı olan hangisidir?', 'Bu dili gençken öğrenmediğim için şimdi zorlanıyor ve üzülüyorum.', ['Gençliğimde bu dili öğrendiğim için şimdi hiç zorlanmıyorum.', 'Bu dili gelecekte, emekli olduktan sonra öğrenmeyi düşünüyorum.', 'Bu dili öğrenmenin hiç gereği yok.'], 'Gerçekleşmemiş bir geçmiş koşul ve bugünkü zorluk, pişmanlığı anlatır; ilk seçenek bu anlamı korur.'),
  ('Ödevini yine unutan öğrencisine öğretmen "Aferin, yine harika bir iş çıkardın!" dedi. Öğretmenin bu sözünde hangi anlatım vardır?', 'Alay yoluyla eleştiri', ['İçten gelen bir övgü ve takdir duygusu', 'Bir tahmin ve olasılık', 'Bir koşula bağlı öneri'], 'Sözün görünürdeki anlamı övgüdür ama durum (ödevin unutulması) bunun tersini gösterir; öğretmen alaycı bir dille eleştirmektedir.'),
  ('Aşağıdaki cümlelerin hangisinde söylenen sözün tersi kastedilerek ironi yapılmıştır?', 'Yağmurda ıslanıp eve gelen kardeşime "Hava ne güzelmiş, belli!" dedim.', ['Hava bugün gerçekten çok güzel, hadi hep birlikte parka gidelim.', 'Yağmur yağınca şemsiyemi açtım.', 'Islanmamak için otobüs durağında bekledim.'], 'Yağmurda ıslanan birine havanın güzel olduğunu söylemek, sözün tersini kastetmektir; bu ironidir.'),
  ('"Ağzı var dili yok" sözü bir kişi için söylendiğinde hangi anlam kastedilir?', 'Çok sessiz, kendini savunmayan biri olduğu', ['Konuşamayan, dili tutulmuş biri olduğu', 'Çok konuşan, duyduğunu herkese anlatan dedikoducu biri olduğu', 'Yemek yemeyi çok seven biri olduğu'], 'Söz, gerçek anlamıyla değil, "çok sessiz, kimseye karşılık vermeyen" anlamıyla, yani kinayeli olarak kullanılır.'),
  ('"Kızın yanakları elma gibi kırmızıydı." cümlesinde benzetmenin öğeleri için hangisi doğrudur?', 'Benzeyen yanaklar, benzetilen elma, benzetme yönü kırmızılıktır.', ['Benzeyen elma, benzetilen yanaklardır.', 'Benzetme yönü "gibi" sözcüğüdür, benzeyen ise kırmızılıktır.', 'Cümlede benzetme edatı yoktur.'], 'Yanaklar elmaya kırmızılık yönünden benzetilmiş; "gibi" ise benzetme edatıdır.'),
  ('"Dağ, karşısındaki ovaya: \'Senin bereketin benim sularımdandır.\' dedi." cümlesinde hangi söz sanatları bir aradadır?', 'Kişileştirme ve konuşturma', ['Abartma ve ironi', 'Benzetme ve ad aktarması', 'Güzel adlandırma ve dolaylama'], 'Dağa konuşma yeteneği verilmiştir; konuşturma, kişileştirmeyi de içerir.'),
  ('"Kahve fincanı masanın kenarında, düşmekten korkarak titriyordu." cümlesinde kişileştirme hangi sözle sağlanmıştır?', 'Düşmekten korkmak', ['Masanın kenarında durmak', 'Kahve fincanı olmak', 'Bir masaya konulmak ve unutulmak'], 'Korku duygusu insana özgüdür; bu duygunun fincana yüklenmesi kişileştirme yapar.'),
  ('"Zaman, en iyi ilaçtır." cümlesinde zaman neye hangi yönden benzetilmiştir?', 'İlaca, acıları iyileştirmesi yönünden', ['Doktora, hastalık teşhis etmesi yönünden', 'Saate, hızlı ilerlemesi yönünden', 'Eczaneye, her yerde bulunması yönünden'], 'Zaman, acıları dindirip insanı iyileştirmesi bakımından ilaca benzetilmiştir.'),
  ('"Ne kadar da çalışkansın, sabahtan beri tek bir sayfa okudun!" cümlesinde konuşanın asıl amacı nedir?', 'Karşısındakinin tembelliğini alaycı biçimde eleştirmek', ['Karşısındakinin çalışkanlığını övmek', 'Okunacak sayfa sayısını öğrenmek', 'Karşısındakine daha hızlı okuyabileceği bir yöntem önermek'], 'Görünürde övgü vardır ama tek sayfa okumak bunun tersini gösterir; söz alaycı bir eleştiridir.'),
  ('Aşağıdakilerden hangisi tanım cümlesi değildir?', 'Geçen yaz tatilimizi Ayvalık\'taki dedemin evinde geçirdik.', ['Sözlük, bir dilin sözcüklerini belli bir düzende sıralayıp açıklayan eserdir.', 'Mimari, yapı tasarlama ve kurma sanatıdır.', 'Atlas, haritaların bir araya getirildiği kitaptır.'], 'Bir kavramın ne olduğunu açıklamayan, yalnızca yaşanmış bir olayı aktaran cümle tanım cümlesi değildir. Sözlük, mimari ve atlas kavramları ise tanımlanmıştır.'),
  ('"Mutluluk, bir kuş gibidir; yakalamaya çalıştıkça uzaklaşır." cümlesi bir tanım cümlesinden nasıl ayrılır?', 'Kavramı bir benzetmeyle ve yorumla açıklar.', ['Kavramı sözlükteki anlamıyla açıklar.', 'Kavramın sayısal verilerini sunar.', 'Kavramın tarih içindeki gelişimini dönem dönem anlatır.'], 'Cümle mutluluğu nesnel olarak tanımlamaz, onu bir kuşa benzeterek kişisel bir yorum yapar.'),
  ('"Kesinlikle yarın gelirim ama belki gelemem." cümlesindeki sorunun kaynağı nedir?', 'Kesinlik ve olasılık bildiren sözlerin bir arada kullanılması', ['Cümlede yüklem bulunmaması', 'Zaman bildiren "yarın" sözcüğünün yanlış yerde ve yanlış yazılması', 'Cümlenin soru biçiminde kurulması'], '"Kesinlikle" yargıyı kesinleştirirken "belki" olasılık bildirir; iki söz birbiriyle çelişir.'),
  ('"Bu filmi izlemeden kimse onun hakkında konuşmamalı." cümlesiyle aynı anlamı taşıyan hangisidir?', 'Filmi izlemeyen, onun hakkında görüş bildirmemeli.', ['Filmi izleyenler onun hakkında konuşmamalı.', 'Film hakkında herkes konuşabilir.', 'Filmi izlemek için önce eleştirileri okumak gerekir.'], 'İki cümle de görüş bildirmeyi filmi izleme koşuluna bağlar.'),
  ('"Ağaçlar, kökleri sağlam olduğu sürece fırtınalara dayanır." cümlesiyle anlamca en yakın cümle hangisidir?', 'Kökü güçlü olan ağacı fırtına yıkamaz.', ['Fırtınalar ağaçların köklerini güçlendirir.', 'Kökü zayıf olan ağaçlar fırtınada daha çok meyve verir.', 'Fırtınalı havalarda ağaçların altında durmak tehlikelidir.'], 'İki cümle de ağacın dayanıklılığını köklerin sağlamlığına bağlar.'),
  ('"Eleştirmenler romanı beğenmese de ... ." cümlesinin anlamca en uygun tamamlanışı hangisidir?', 'okurlar kitaba büyük ilgi gösterdi', ['eleştirmenler kitabı çok övdü', 'kitap hiç satılmadı ve kısa sürede unutuldu', 'okurlar da romanı hiç sevmedi'], '"-se de" karşıtlık kurar; eleştirmenlerin beğenmemesine karşın okurların ilgi göstermesi bu karşıtlığı sağlar.'),
  ('"Bu ilaç, hastalığın belirtilerini hafifletir ama ... ." cümlesi hangisiyle tamamlanırsa anlam bütünlüğü sağlanır?', 'hastalığı kökünden iyileştirmez', ['belirtileri tamamen yok eder', 'hastalığın belirtilerini hafifletir', 'hiçbir yan etkisi yoktur ve çok ucuzdur'], '"Ama" bağlacı karşıt bir yargı bekler; belirtileri hafifletmek ile hastalığı iyileştirmemek karşıtlık oluşturur.'),
  ('"Ne kadar çok okursan ... ." cümlesinin anlamca en uygun devamı hangisidir?', 'o kadar geniş bir sözcük dağarcığına sahip olursun', ['o kadar az kitap tanırsın', 'kitapların fiyatı o kadar düşer', 'o kadar geç yatarsın ama sabahları erken kalkarsın'], '"Ne kadar ... o kadar" yapısı orantılı bir neden-sonuç ilişkisi kurar; çok okumak sözcük dağarcığını genişletir.'),
  ('"Bu sınavı kazanmayacağını bilmiyor değildi." cümlesinin anlamı aşağıdakilerden hangisidir?', 'Sınavı kazanamayacağını biliyordu.', ['Sınavı kazanacağından emindi.', 'Sınavın sonucunu hiç merak etmiyordu.', 'Sınava girip girmeyeceğine karar veremedi.'], '"Bilmiyor değildi" yapısında iki olumsuzluk birbirini götürür; anlam "biliyordu"dur.'),
  ('Aşağıdaki cümlelerin hangisi biçimce olumsuz, anlamca olumludur?', 'Ona yardım etmemek elimde değildi.', ['Ona hiç yardım etmedim.', 'Yardım istemesine rağmen ilgilenmedim.', 'Ona yardım etmek istemedim.'], '"Yardım etmemek elimde değildi", "yardım etmek zorunda kaldım, ettim" anlamına gelir; biçim olumsuz, anlam olumludur.'),
  ('"Sorunu çözmek için elinden geleni yapmadı değil." cümlesinden hangisi anlaşılır?', 'Sorunu çözmek için çaba göstermiştir.', ['Sorunu çözmek için hiçbir şey yapmamıştır.', 'Sorunu çözmesine izin verilmemiştir.', 'Sorunu çözmek istememiştir.'], '"Yapmadı değil" yapısındaki çift olumsuzluk olumlu anlam verir: elinden geleni yapmıştır.'),
  ('"Bu yaşta bir çocuktan bu kadar olgun bir davranış beklenir mi?" sorusu için hangisi söylenebilir?', 'Yanıt beklemeyen, "beklenmez" anlamı taşıyan bir sözde sorudur.', ['Karşıdakinden bilgi isteyen gerçek bir sorudur.', 'Bir öneriyi soru biçiminde, dolaylı yoldan dile getirmektedir.', 'Bir tahmini ölçmek için sorulmuştur.'], 'Soru biçiminde kurulsa da yanıt beklenmez; çocuğun davranışının beklenenin üstünde olduğu vurgulanır.'),
  ('Aşağıdaki soru cümlelerinin hangisi gerçekten bilgi almak amacıyla sorulmuştur?', 'Toplantı saat kaçta başlayacak?', ['Bu güzelliğe kim hayran olmaz ki?', 'İnsan annesini hiç unutur mu?', 'Bu kadar emek boşa gider mi hiç?'], 'İlk soru belirli bir bilgi (saat) istemektedir. Diğerleri yanıt beklemeyen, bir yargıyı pekiştiren sözde sorulardır.'),
  ('"Kim demiş bu yolun sonu karanlık diye?" cümlesinde hangi anlam vardır?', 'Yolun sonunun karanlık olmadığı vurgulanmıştır.', ['Bu sözü kimin söylediği merak edilmiştir.', 'Yolun sonunun karanlık olduğu kesin olarak bildirilmiştir.', 'Karanlıkta yola çıkılması önerilmiştir.'], 'Soru biçimindeki bu cümle, bir düşünceye itiraz eder: yolun sonu karanlık değildir.'),
  ('"Sanatçı, eserini yalnızca kendisi için değil, toplum için de üretir." cümlesinden aşağıdakilerin hangisi çıkarılabilir?', 'Sanat eserinin toplumsal bir yönü de vardır.', ['Sanatçı eserini yalnızca kendisi için üretir.', 'Toplum, sanatçının eserlerini beğenmez.', 'Sanatçının eseri toplumdan bağımsızdır.'], '"Yalnızca kendisi için değil, toplum için de" ifadesi eserin toplumu da gözettiğini, toplumsal bir işlevi olduğunu anlatır.'),
  ('"Çocuklar, büyüklerin söylediklerinden çok yaptıklarını örnek alır." cümlesinden aşağıdakilerden hangisi çıkarılabilir?', 'Davranışlarımız sözlerimizden daha etkili bir eğitim aracıdır.', ['Çocuklar büyüklerin sözlerini hiç dinlemez.', 'Büyükler, çocuklara sözlü olarak hiçbir zaman öğüt vermemelidir.', 'Çocuklar yalnızca okulda öğrenir.'], 'Cümle, çocukların davranışları sözlerden daha çok örnek aldığını söyler; "hiç dinlemez" gibi kesin genellemeler cümlede yoktur.'),
  ('"Bir daha bu saatte eve gelirsen kapıyı açmam, ona göre!" cümlesinde hangi anlam ağır basar?', 'Gözdağı verme', ['Kibarca rica etme', 'İçten teşekkür etme', 'Övgüde bulunma'], 'Bir davranışın tekrarlanması durumunda olumsuz bir sonuçla karşılaşılacağı bildirilmiş; "ona göre" sözü gözdağını pekiştirir.'),
  ('"Ah, o fırsatı nasıl da kaçırdım; elimin altındaydı oysa!" cümlesinde hangi duygu vardır?', 'Hayıflanma', ['Övünme', 'Sevinç ve coşku', 'Umut'], 'Elde edilebilecekken kaçırılan bir fırsat için duyulan üzüntü hayıflanmadır.'),
  ('Aşağıdaki cümlelerin hangisinde şaşırma duygusu anlatılmıştır?', 'Aa, sen ne zaman bu kadar büyüdün böyle!', ['Seni yıllardır göremediğim için çok özledim.', 'Bu işi bu kadar geciktirmeni hiç beklemezdim, çok kırıldım.', 'Yarın erkenden yola çıkmayı düşünüyorum.'], '"Aa" ünlemi ve şaşkınlık bildiren soru-ünlem yapısı, beklenmedik bir durum karşısındaki hayreti anlatır.'),
  ('Öğretmen "Yarın sınav var." dedi. Bu söz dolaylı anlatımla nasıl aktarılır?', 'Öğretmen, ertesi gün sınav olduğunu söyledi.', ['Öğretmen: "Yarın sınav var." dedi.', 'Öğretmen, yarın sınav olmayacağını söyledi.', 'Öğretmen, dün sınav yaptığını anlattı ve bizi kutladı.'], 'Dolaylı anlatımda söz, aktaranın kendi cümlesine dönüştürülür; tırnak işareti kullanılmaz.'),
  ('Aşağıdaki cümlelerin hangisinde doğrudan anlatım kullanılmıştır?', 'Dedem "Ağaç dikmeyen, gölgesinde oturamaz." derdi.', ['Dedem, ağaç dikmenin önemini sık sık anlatırdı.', 'Dedem bahçeye her yıl yeni ağaçlar dikerdi.', 'Dedem, ağaç dikmeyenin gölgede oturamayacağını söylerdi.'], 'Doğrudan anlatımda başkasının sözü hiç değiştirilmeden, tırnak içinde aktarılır.'),
  ('"Bu kitabı bana kütüphaneden ağabeyim getirdi." cümlesinde vurgulanan öğe hangisidir?', 'Kitabı getiren kişi', ['Getirilen nesnenin ne olduğu', 'Kitabın kime getirildiği', 'Kitabın nereden getirildiği'], 'Türkçede vurgu genellikle yüklemden hemen önceki öğeye düşer; burada yüklemden önce özne "ağabeyim" gelir, yani kitabı getiren kişi vurgulanır.'),
  ('"Sınavı kazandığını en son ben öğrendim." cümlesinde vurgu hangi öğe üzerindedir?', 'Ben', ['Sınavı kazandığını', 'En son', 'Öğrendim'], 'Yüklemden hemen önce gelen "ben" öznesi vurgulanmıştır; haberi öğrenenin kim olduğu öne çıkar.'),
  ('"Bu kadar gürültüye dayanamıyorum artık; ya sessiz olun ya da dışarı çıkın!" cümlesinde konuşanın tutumu nasıldır?', 'Sabrı tükenmiş biçimde uyarıda bulunmaktadır.', ['Karşısındakilere teşekkür etmektedir.', 'Gürültünün nedenini merak edip sormaktadır.', 'Karşısındakilere bir öneriyi rica ederek sunmaktadır.'], '"Dayanamıyorum artık" sözüyle sabrın tükendiği belirtilmiş, ardından seçenekli bir uyarı yapılmıştır.'),
  ('"Kitabın ilk bölümünü okuyunca kafamdaki bütün sorular aydınlandı." cümlesinde "aydınlanmak" sözcüğü hangi anlamda kullanılmıştır?', 'Mecaz anlam', ['Gerçek anlam', 'Yan anlam', 'Terim anlam'], 'Soruların ışık alması söz konusu değildir; sözcük "açıklığa kavuşmak" anlamında mecazdır.'),
  ('"Yıllarca süren yalnızlık, onun kalbini taşa çevirmişti." cümlesindeki anlatımla ilgili hangisi doğrudur?', 'Duygusuzlaşmak, mecaz yoluyla anlatılmıştır.', ['Bir organın gerçekten taşlaştığı anlatılmıştır.', 'Kalp sözcüğü tıp terimi olarak kullanılmıştır.', 'Yalnızlığın nedeni açıklanıp kanıtlanmıştır.'], '"Kalbi taşa dönmek", merhametini ve duyarlılığını yitirmek anlamında mecaz bir anlatımdır.'),
  ('Aşağıdaki cümlelerin hangisinde "nota" sözcüğü müzik terimi olarak kullanılmıştır?', 'Kemancı, şarkının notalarını önündeki sehpaya yerleştirdi.', ['Dışişleri Bakanlığı komşu ülkeye sert bir nota verdi.', 'Bu yıl karnemdeki notlar çok yüksek.', 'Defterimin kenarına öğretmenin söylediklerini kısa bir not olarak düştüm.'], 'Müzikte nota, sesleri gösteren işaretlerdir. Dışişlerindeki "nota" ise diplomaside resmî yazı anlamında başka bir terimdir.'),
  ('"Kumaşın rengi güneşte solmuş, eski parlaklığından eser kalmamıştı." cümlesinde "solmak" sözcüğü için hangisi doğrudur?', 'Gerçek anlamda, rengin canlılığını yitirmesini anlatır.', ['Mecaz anlamda, insanın gücünü yitirmesini anlatır.', 'Terim olarak, kimyadaki bir tepkimeyi bildirir.', 'Yan anlamda, bitkilerin yapraklarının sararıp kurumasını anlatır.'], 'Kumaşın renginin solması, rengin canlılığını yitirmesidir; sözcük bu cümlede gerçek anlamıyla yer alır.'),
  ('"Kapı" sözcüğü aşağıdakilerin hangisinde "bir şeye ulaşma yolu, olanak" anlamında kullanılmıştır?', 'Bu burs, ona yurt dışında okumanın kapısını açtı.', ['Kapıyı kilitlemeyi unutmuş, içeri hırsız girmiş.', 'Kapının zili çalınca köpek havlamaya başladı.', 'Bahçe kapısı rüzgârda bütün gece sürekli çarpıp durdu.'], 'Okumanın kapısını açmak, ona olanak sağlamak demektir; mecaz bir kullanımdır.'),
  ('"Köyün başında büyük bir çınar ağacı vardı." cümlesinde "baş" sözcüğü hangi anlamdadır?', 'Bir yerin giriş bölümü, başlangıcı', ['İnsan vücudunun en üst bölümü', 'Bir topluluğu yöneten kimse', 'Bir olayın ilk nedeni, kaynağı ve çıkış noktası'], 'Köyün başı, köyün girişi ya da başlangıç yeri demektir; organ adının yan anlamıdır.'),
  ('Coğrafyada denize doğru uzanan kara parçasına yüzümüzdeki bir organın adının verildiği görülür. Bu yan anlam, aşağıdaki cümlelerin hangisinde yer alır?', 'Gemi, burnu geçince dalgalar yatıştı.', ['Soğuk havada burnu kızardı.', 'Burnundan soğuk algınlığı yüzünden nefes alamıyordu.', 'Çiçeği koklamak için burnunu yaklaştırdı.'], 'Coğrafyada denize doğru uzanan kara parçasına "burun" denir; bu, organa benzetmeyle oluşmuş yan anlamdır.'),
  ('"Bu sene okulda yeni bir bilim kulübü kurduk." cümlesindeki "kurmak" sözcüğü hangi anlamdadır?', 'Bir örgütü ya da topluluğu oluşturmak', ['Bir aleti çalışır duruma getirmek', 'Bir masayı yemek için hazırlamak', 'Bir düşünceyi kafada uzun uzun tasarlamak'], 'Kulüp kurmak, bir topluluğu oluşturmak, örgütlemektir.'),
  ('"Kararlarında hep ılımlı bir yol izlerdi." cümlesinde "ılımlı" sözcüğü hangi anlamda kullanılmıştır?', 'Aşırılıktan kaçınan, ölçülü', ['Ilık suyla yıkanmış', 'Sıcaklığı yüksek olan', 'Kararsız, ne yapacağını bilemeyen ve korkak olan'], '"Ilımlı", uç noktalara gitmeyen, orta yolu tutan anlamındadır.'),
  ('Aşağıdaki cümlelerin hangisinde eş anlamlı sözcükler bir arada kullanılarak anlam pekiştirilmiştir?', 'Bu proje, yıllardır süren emeğin ve çabanın ürünüdür.', ['Gece ile gündüz bu kentte birbirine karışır.', 'Zengin de yoksul da aynı kurallara uymak zorunda.', 'Yaşlılar ve gençler, bayram sofrasında aynı masanın çevresinde oturdu.'], '"Emek" ve "çaba" yakın anlamlıdır; birlikte kullanılarak anlam güçlendirilmiştir. Diğer cümlelerde karşıt kavramlar vardır.'),
  ('"Yeni gelen öğrenci önceleri çok çekingendi, sonra herkesle kaynaştı." cümlesindeki "çekingen" sözcüğünün karşıt anlamlısı hangisidir?', 'atılgan', ['utangaç', 'sessiz', 'içine kapanık'], '"Çekingen", kendini geri planda tutan demektir; karşıtı cesurca öne çıkan "atılgan"dır.'),
  ('"Kır" sözcüğü aşağıdaki cümlelerin hangisinde "şehir dışındaki açık alan" anlamındadır?', 'Hafta sonu kırda piknik yaptık.', ['Dedemin saçları kır olmuş.', 'Dalı dizinin üstünde kır da ateşe at.', 'Kır atını çeşmeden suladı.'], '"Kır" sözcüğü açık alan, ak düşmüş saç ya da at rengi ve "kırmak" eyleminin emri olarak sesteştir. İlk cümlede açık alan anlamı vardır.'),
  ('"Bütün sınıf, öğretmenin sorusuna aynı anda el kaldırdı." cümlesinde "sınıf" sözcüğü neyi karşılamaktadır?', 'Sınıftaki öğrencileri', ['Okulun bir odasını', 'Bir okul binasını', 'Öğrencilerin yaş grubunu ve düzeyini'], 'El kaldıran sınıfın kendisi değil, içindeki öğrencilerdir; bu, yer ile orada bulunanlar arasındaki ilişkiye dayanan ad aktarmasıdır.'),
  ('"Kara elmas" sözüyle halk arasında genellikle hangisi kastedilir?', 'Kömür', ['Petrol', 'Altın', 'Mermer'], 'Kömür, değerli ve kara rengi nedeniyle "kara elmas" diye dolaylı olarak anılır.'),
  ('"İpe un sermek" deyimi hangi davranışı anlatır?', 'Bir isteği yerine getirmemek için türlü bahaneler bulmak', ['Ev işlerini titizlikle yapmak', 'Ekmek yapmak için hazırlık yapmak', 'Bir işi zamanında, eksiksiz ve kimseyi bekletmeden bitirmek'], 'Olmayacak bir gerekçe (ipe un sermek) öne sürmek, isteneni yapmamak için bahane bulmak demektir.'),
  ('"Kendini dev aynasında görmek" deyimi kimin için kullanılır?', 'Kendine olduğundan çok daha fazla değer veren biri için', ['Ayna karşısında saatlerce süslenerek vakit geçiren biri için', 'Kendini yetersiz ve güçsüz gören biri için', 'Boyunun uzunluğuyla övünen bir sporcu için'], 'Deyim, kendini olduğundan büyük, önemli ve yetenekli sanmayı anlatır.'),
  ('"Nalıncı keseri gibi kendine yontmak" deyimiyle eleştirilen tutum hangisidir?', 'Her durumdan yalnızca kendi çıkarını gözetmek', ['Bir işi büyük bir ustalıkla yapmak', 'Başkalarına karşılık beklemeden sürekli yardım etmek', 'Eşyalarını kendi elleriyle onarmak'], 'Deyim, her şeyi kendi yararına yorumlayan, bencil kişileri anlatır.'),
  ('"Taş kesilmek" deyimi aşağıdaki cümlelerin hangisinde anlamına uygun kullanılmıştır?', 'Kazayı gözleriyle görünce olduğu yerde taş kesildi.', ['Bahçedeki taşları kesip duvar ördü.', 'Taş kesilince eski kaldırımın yerine yenisini yaptık.', 'Sevincinden taş kesildi, dans etmeye başladı.'], '"Taş kesilmek", şaşkınlık ya da korkudan donup kalmaktır; kazayı gören kişi için uygundur. Dans etmek ise hareketsizliğe aykırıdır.'),
  ('"Yeni gelen öğretmen, sınıfın ... için birkaç gün öğrencileri sessizce gözlemledi." cümlesinde boşluğa hangi deyim getirilmelidir?', 'nabzını tutmak', ['gözünden düşmek', 'ağzına bakmak', 'kulağını bükmek'], '"Nabzını tutmak", birinin ya da bir topluluğun düşüncesini, eğilimini anlamaya çalışmaktır.'),
  ('"El üstünde tutmak" deyimi aşağıdakilerin hangisinde doğru kullanılmıştır?', 'Köylüler, okullarına gelen genç öğretmeni el üstünde tuttu.', ['Ağır kutuyu el üstünde tutarak taşıdı.', 'Yanlış yaptığı için onu el üstünde tuttular ve cezalandırdılar.', 'Hırsızı yakalayıp el üstünde tuttular.'], 'Deyim, birine çok saygı ve sevgi göstermek anlamındadır; ceza ya da hırsızla bu anlam bağdaşmaz.'),
  ('"Sınav tarihi yaklaştıkça öğrenciler ... ; kimse dışarı çıkmıyordu." cümlesinde boşluğa getirilecek deyim hangisidir?', 'kitaplara gömüldü', ['havaya girdi', 'ipin ucunu kaçırdı', 'eli kolu bağlandı'], '"Kitaplara gömülmek", kendini tümüyle derslerine vermek anlamındadır ve kimsenin dışarı çıkmamasıyla uyumludur.'),
  ('"Komşumuzun kızı yıllardır beklediği haberi alınca ... ." cümlesinde boşluğa getirilen deyimlerden hangisi anlamı bozar?', 'burnundan soludu', ['havalara uçtu', 'ağzı kulaklarına vardı', 'sevinçten ağladı'], 'Yıllardır beklenen haber sevinç bildirir; "burnundan solumak" ise çok öfkelenmek anlamındadır ve cümleye uymaz.'),
  ('"Dost kara günde belli olur." atasözüyle örtüşen durum hangisidir?', 'Hastalandığında her gün yanına gelen tek arkadaşının Can olması', ['Doğum gününde herkesin kutlamaya gelmesi', 'Tatile birlikte gittiği arkadaşlarıyla deniz kenarında çok eğlenmesi', 'Yeni taşındığı mahallede komşularıyla tanışması'], 'Gerçek dost, sıkıntılı anlarda yanımızda olan kişidir; Can\'ın hastalıkta yanında olması bunu gösterir.'),
  ('"Mum dibine ışık vermez." atasözü hangi durumu anlatmaktadır?', 'Herkese yardım eden birinin kendi yakınlarına yararının dokunmaması', ['Mumların küçük bir alanı aydınlatması', 'Elektrik kesintilerinde mum kullanılması', 'Bir kişinin herkesten çok kendi ailesine ve yakınlarına yardım etmesi'], 'Atasözü, başkalarına iyilik eden birinin en yakınındakilere bu iyiliği gösterememesini anlatır.'),
  ('"Ak akçe kara gün içindir." atasözüne uygun davranan kişi hangisidir?', 'Kazancının bir bölümünü beklenmedik durumlar için biriktiren Elif', ['Bütün parasını tatile harcayan Selim', 'Borç alarak yeni bir telefon alan Kerem', 'Parasını kimseye vermeyip hiçbir ihtiyacı için bile harcamayan Nur'], 'Atasözü, iyi günlerde kazanılan paranın kötü günler için saklanmasını öğütler.'),
  ('"Allah kavuştursun" sözü hangi durumda söylenir?', 'Bir yakını uzağa giden birini teselli ederken', ['Yeni bir işe başlayan birini içtenlikle kutlarken', 'Yemekten sonra teşekkür ederken', 'Sınavı kazanan birini tebrik ederken'], 'Yakını askere ya da uzağa giden birine, bir an önce kavuşmaları dileğiyle söylenen kalıplaşmış bir sözdür.'),
  ('"Sıhhatler olsun" sözü genellikle kime söylenir?', 'Banyo yapmış ya da tıraş olmuş birine', ['Hasta birine hastanede ziyaret sırasında', 'Yolculuğa çıkan birine', 'Doğum günü olan birine'], '"Sıhhatler olsun", yıkanmış, tıraş olmuş ya da saçını kestirmiş kişilere söylenen kalıplaşmış bir iyi dilektir.'),
  ('"Kütüphanenin sessizliği, çalışmaya odaklanmamı kolaylaştırdı." cümlesinde "sessizlik" ile "odaklanma" arasında nasıl bir ilişki kurulmuştur?', 'Sessizlik, odaklanmanın nedeni olarak gösterilmiştir.', ['Odaklanma, sessizliğin amacı olarak gösterilmiştir.', 'İkisi birbiriyle karşılaştırılarak biri üstün tutulmuştur.', 'Sessizlik, odaklanmanın gerçekleşmesi için bir koşul olarak sunulup sorgulanmıştır.'], 'Cümlede sessizliğin odaklanmayı kolaylaştırdığı belirtilerek bir neden-sonuç ilişkisi kurulmuştur.'),
  ('Aşağıdaki cümlelerin hangisinde neden-sonuç ilişkisi "-dan" ekiyle sağlanmıştır?', 'Yorgunluktan gözlerini açık tutamıyordu.', ['Okuldan eve yürüyerek döndü.', 'Bu kitabı kütüphaneden aldım.', 'Geçen yaz Ankara\'dan İzmir\'e gece kalkan trenle gittik.'], '"Yorgunluktan" sözcüğündeki "-dan" eki neden bildirir. Diğer cümlelerde "-dan" eki uzaklaşma, çıkış yeri anlamındadır.'),
  ('"Fiyatlar artınca alışverişi azalttık." cümlesine anlamca en yakın olan hangisidir?', 'Fiyat artışı nedeniyle daha az alışveriş yaptık.', ['Alışverişi azaltmak için fiyatları artırdık.', 'Fiyatlar artarsa alışverişi azaltırız.', 'Fiyatlar artmadan önce, tedbir olarak alışverişi azalttık.'], 'Asıl cümlede fiyat artışı, alışverişin azalmasının nedenidir; ilk seçenek bu neden-sonuç ilişkisini korur.'),
  ('"Bilet bulabilirsek hafta sonu tiyatroya gideceğiz." cümlesinden kesin olarak hangisi anlaşılır?', 'Tiyatroya gidilmesi bilet bulunmasına bağlıdır.', ['Hafta sonu kesinlikle tiyatroya gidilecektir.', 'Biletler birkaç gün önceden internetten satın alınmıştır.', 'Tiyatro oyunu iptal edilmiştir.'], '"-ebilirsek" koşul bildirir; gitmek bilet bulma koşuluna bağlanmıştır, kesinlik yoktur.'),
  ('"Bu kitabı okumadan o filmi izlersen hikâyenin inceliklerini kaçırabilirsin." cümlesinde koşul nedir?', 'Kitabı okumadan filmi izlemek', ['Hikâyenin inceliklerini kaçırmak', 'Kitabı okuyup filmi izlememek', 'Filmi izledikten sonra kitabı da hemen okumak'], '"İzlersen" sözcüğündeki koşul eki, kitabı okumadan filmi izleme durumuna bağlanmıştır; incelikleri kaçırmak ise sonuçtur.'),
  ('"Bu yılki kış, geçen yılınkinden çok daha sert geçti." cümlesindeki karşılaştırma hangi yönden yapılmıştır?', 'Kışların şiddeti bakımından', ['Kışların süresi bakımından', 'Yağan karın rengi bakımından', 'Kışın başladığı tarih bakımından'], '"Sert" sözcüğü, kışın şiddetini anlatır; iki yılın kışı bu yönden karşılaştırılmıştır.'),
  ('Aşağıdaki cümlelerin hangisinde iki varlık arasında bir benzerlik değil, farklılık vurgulanmıştır?', 'İkiz kardeşler görünüşte aynı olsalar da huyları birbirine hiç benzemez.', ['Kızı da annesi gibi resim yapmaya meraklıdır.', 'Bu ev, çocukluğumda ailece oturduğumuz o eski eve çok benziyor.', 'İki kardeş de babaları gibi öğretmen oldu.'], 'İkizlerin huylarının birbirine benzemediği söylenerek farklılık öne çıkarılmıştır; diğerlerinde benzerlik vurgulanır.'),
  ('"Kentin yeni müzesi, eskisine göre hem daha geniş hem de daha aydınlık." cümlesinden hangisi çıkarılabilir?', 'Eski müze, yenisine göre daha dar ve loştur.', ['Yeni müze, eskisinden daha dar ve karanlıktır.', 'İki müze de aynı genişliktedir.', 'Eski müze yıkılmış ve yerine yenisi yapılmıştır.'], 'Yeni müze daha geniş ve aydınlıksa, eskisi ona göre daha dar ve loştur. Eskisinin yıkıldığı ise cümlede yoktur.'),
  ('"Bu dağ köyünde yaşayanlar, en az şehirdekiler kadar teknolojiyi yakından izliyor." cümlesiyle anlatılmak istenen nedir?', 'Köylülerin teknolojiyi izleme konusunda şehirlilerden geri kalmadığı', ['Köylülerin teknolojiden hiç haberi olmadığı', 'Şehirdekilerin teknolojiyle köylüler kadar bile ilgilenmediği ve geri kaldığı', 'Köyde teknoloji kullanmanın yasak olduğu'], '"En az ... kadar" yapısı, köylülerin şehirlilerle en azından eşit düzeyde olduğunu anlatır.'),
  ('"Ödevini zamanında bitirdi, böylece hafta sonunu ailesiyle geçirebildi." cümlesindeki "böylece" sözcüğü hangi ilişkiyi kurmaktadır?', 'Bir eylemin doğurduğu sonucu bağlama', ['İki karşıt düşünceyi birbirine bağlama', 'Bir eylemin koşulunu belirtme', 'Bir varsayımda bulunma'], '"Böylece", ödevin bitirilmesinin bir sonucunu, ailesiyle vakit geçirebilmeyi bağlar.'),
  ('"Çok güzel", "etkileyici", "sıkıcı" gibi sözcüklerle kurulan yargılar genellikle neden öznel sayılır?', 'Değerlendirmeler kişiden kişiye değişebileceği için', ['Bu sözcüklerin tamamı yabancı dillerden geçmiş, kökeni Türkçe olmayan sözcükler olduğu için', 'Cümlede yüklem bulunmadığı için', 'Bu yargılar her zaman yanlış olduğu için'], 'Güzel ya da sıkıcı bulma, bireyin zevkine bağlıdır; ölçülüp kanıtlanamaz.'),
  ('"Yarın sabah kesinlikle erken kalkacağım, ama alarmı duyar mıyım bilmiyorum." cümlesinde konuşanın tutumu nasıldır?', 'Kararlı olsa da başarıp başaramayacağından emin değildir.', ['Erken kalkmayı hiç istememektedir.', 'Alarmın kesinlikle çalacağını ve onu uyandıracağını çok iyi bilmektedir.', 'Geç kalktığı için pişmanlık duymaktadır.'], 'Konuşan, erken kalkmaya kararlıdır ama alarmı duyup duymayacağı konusunda kuşkuludur.'),
  ('Aşağıdaki cümlelerin hangisinde yargı, ötekilerden farklı olarak kesinlik taşır?', 'Dünya, Güneş\'in çevresinde döner.', ['Bu akşam misafir gelebilir.', 'Sanırım yarın okullar tatil olacak.', 'Belki önümüzdeki yıl başka bir şehre taşınırız.'], 'Dünya\'nın Güneş\'in çevresinde dönmesi kesinleşmiş bir bilgidir. Diğerlerinde "-ebilir", "sanırım", "belki" ile olasılık bildirilmiştir.'),
  ('"Yaşlılar teknolojiden anlamaz, onlara telefon kullanmayı öğretmek boşuna." cümlesindeki düşünce nasıl değerlendirilebilir?', 'Bir topluluk hakkında genelleyici bir ön yargıdır.', ['Bilimsel araştırmalarla kanıtlanmış, nesnel bir bilgidir.', 'Yaşlılara yönelik içten bir övgüdür.', 'Teknolojiyle ilgili tarafsız bir tanımdır.'], 'Bütün yaşlıların teknolojiden anlamadığını söylemek, bireyleri tanımadan yapılmış bir genellemedir; ön yargı içerir.'),
  ('"Bu kentte trafik bir saattir hiç ilerlemiyor; bir kaplumbağa bile bizden önce varırdı." cümlesinde hangi anlatımlar bir arada bulunur?', 'Yakınma ve abartma', ['Öneri ve tanım', 'Pişmanlık ve geleceğe umut', 'Övgü ve teşekkür'], 'Trafikten şikâyet edilmesi yakınma, kaplumbağanın daha önce varacağı ise abartmadır.'),
  ('Bir arkadaşınız sınav kaygısı yaşadığını söylüyor. Aşağıdaki cümlelerden hangisi ona yönelik bir öneri niteliği taşır?', 'Sınavdan önceki gece erken yatıp iyi dinlenmeyi dene.', ['Ben de geçen yıl çok kaygılanmıştım.', 'Sınavlar herkes için zordur.', 'Kaygılanman çok doğal, emin ol herkes sınavdan önce böyle hisseder.'], 'Öneri, karşıdakine yapabileceği somut bir davranışı gösterir; erken yatıp dinlenmek böyle bir yoldur.'),
  ('"Belediye, parkları yenilemek yerine önce kırık kaldırımları onarmalıydı." cümlesinde hangi anlam vardır?', 'Yapılan bir tercihe yönelik eleştiri', ['Belediyeye, yaptığı hizmetler için bir teşekkür', 'Geleceğe dair bir tahmin', 'Parkların tanımı ve özellikleri'], '"-malıydı" yapısı, yapılmış olanın yanlış bulunduğunu, başka bir şeyin önce yapılması gerektiğini bildirir; bu bir eleştiridir.'),
  ('Bir okur, okuduğu romanla ilgili "Karakterler canlı ve inandırıcı ama sonu aceleye getirilmiş." diyor. Okurun değerlendirmesi için hangisi doğrudur?', 'Eserin hem güçlü hem de zayıf yönünü belirtmiştir.', ['Eseri yalnızca övmüştür.', 'Eseri yalnızca yermiştir.', 'Esere ilişkin yalnızca nesnel, doğrulanabilir bilgiler vermiştir.'], 'Karakterler övülmüş, romanın sonu ise eleştirilmiştir; değerlendirme iki yönlüdür.'),
  ('Aşağıdaki cümlelerin hangisinde konuşan, yaşadığı bir sıkıntıdan yakınmaktadır?', 'Bu dar ayakkabılar bütün gün ayaklarımı acıttı.', ['Yeni ayakkabılarım çok rahat, hiç çıkarmak istemiyorum.', 'Bu ayakkabıları geçen hafta indirimde aldım.', 'Ayakkabıcı, ayakkabılarımı özenle boyadı.'], 'Dar ayakkabıların ayakları acıtması bir sıkıntıdır ve konuşan bundan şikâyet etmektedir.'),
  ('"Hiç değilse bir kez olsun ona teşekkür etseydim..." cümlesiyle anlatılmak istenen nedir?', 'Teşekkür etmemiş olmanın verdiği üzüntü', ['Teşekkür ettiği için duyduğu mutluluk', 'Gelecekte herkese teşekkür etme konusundaki kararlılığı', 'Teşekkürün gereksiz olduğu düşüncesi'], '"-seydim" yapısı, geçmişte yapılmamış bir eylem için duyulan pişmanlığı anlatır.'),
  ('Yemeği yaktıktan sonra "Ellerine sağlık, çok güzel bir kömür yapmışsın!" diyen kardeşin sözünde hangi anlatım vardır?', 'İğneleme, alaycı söz', ['İçten bir övgü', 'Geleceğe dönük bir tahmin', 'Bir pişmanlık'], 'Yanmış yemeğe "güzel bir kömür" demek, alaycı bir dille durumu iğnelemektir.'),
  ('Aşağıdaki cümlelerin hangisinde benzetme yönü belirtilmiştir?', 'Yolun iki yanındaki kavaklar asker gibi dimdik duruyordu.', ['Kavaklar yolun iki yanına sıralanmıştı.', 'Bu kavaklar dedemin zamanında dikilmiş.', 'Kavakların sararmış yaprakları sonbahar rüzgârında hışırdıyordu.'], 'Kavaklar askere "dimdik durma" yönünden benzetilmiştir; benzetme yönü "dimdik"tir.'),
  ('"Kar taneleri, gökten süzülen beyaz kelebekler gibiydi." cümlesinde kar taneleri kelebeklere hangi yönden benzetilmiştir?', 'Renkleri ve havada hafifçe uçuşmaları', ['Soğuk olmaları', 'Kısa ömürlü olmaları ve çabuk erimeleri', 'Çiçeklere konmaları'], 'Kar taneleri, beyaz renkleri ve havada süzülerek inmeleri bakımından beyaz kelebeklere benzetilmiştir.'),
  ('"Eski saat, duvarda yorgun yorgun tıkırdıyor, geçen yılları sayıyordu." cümlesindeki anlatım için hangisi söylenebilir?', 'Cansız bir varlığa insana özgü nitelikler verilmiştir.', ['Bir hayvan konuşturulmuştur.', 'Saat, gerçek anlamıyla zamanı gösteren bir alet olarak tanıtılmıştır.', 'Cümlede hiçbir söz sanatı yoktur.'], 'Saate yorgunluk ve yılları sayma gibi insana özgü özellikler yüklenmiştir; bu kişileştirmedir.'),
  ('Aşağıdakilerden hangisi "ders kitabı" kavramının tanımı olarak kabul edilebilir?', 'Belirli bir dersin konularını öğretmek amacıyla hazırlanmış kitap', ['Öğrencilerin en sevmediği, her gün çantada taşınan ağır ve kalın kitap', 'Her yıl yenisi alınan renkli bir kitap', 'Okul kütüphanesinde bulunan eski kitaplar'], 'Tanım, kavramın ayırt edici niteliğini, yani bir dersi öğretmek için hazırlanmış olmasını vermelidir; diğerleri kişisel ya da eksik nitelemelerdir.'),
  ('"Doğduğu köyü hiç görmemiş olsa da oranın her sokağını, her evini çocukluğundan hatırlıyordu." cümlesindeki tutarsızlık hangi sözlerden kaynaklanmaktadır?', '"Hiç görmemiş" ile "çocukluğundan hatırlıyordu"', ['"Doğduğu köy" ile "her sokağını, her evini" sözleri', '"Her evini" ile "hatırlıyordu"', '"Olsa da" ile "çocukluğundan"'], 'Hiç görülmemiş bir yerin çocukluktan hatırlanması mümkün değildir; bu iki söz birbiriyle çelişir.'),
  ('"Okumayan bir toplum, düşünmeyi de unutur." cümlesiyle aynı düşünceyi dile getiren cümle hangisidir?', 'Okuma alışkanlığı kaybolan toplumlarda düşünme yetisi de zayıflar.', ['Toplumlar okudukça daha az düşünür.', 'Okumak ile düşünmek arasında hiçbir bağ yoktur, ikisi ayrı yetilerdir.', 'Düşünen toplumlar kitap okumaya gerek duymaz.'], 'İki cümle de okumanın düşünme üzerindeki etkisini vurgular.'),
  ('"Bu romanda yazar, kahramanlarını ... bir dille konuşturmuş; okur, her diyalogda karakterlerin yaşadığı bölgeyi hissediyor." cümlesinde boşluğa hangisi gelmelidir?', 'yöresel', ['resmî', 'bilimsel', 'yapay'], 'Okurun karakterlerin yaşadığı bölgeyi hissetmesi, konuşmaların o yöreye özgü bir dille yazıldığını gösterir.'),
  ('"Gerçek bir dost, ... ; sevincini de üzüntünü de seninle paylaşır." cümlesi hangisiyle tamamlanırsa anlam bütünlüğü sağlanır?', 'yalnızca iyi günlerde değil, kötü günlerde de yanındadır', ['sadece işi düştüğünde seni arar', 'seni hiçbir zaman eleştirmez ve her tartışmada senin haklı çıkmanı sağlar', 'seninle yalnızca eğlenceli zamanlarda buluşur'], 'Cümlenin devamı sevinç ve üzüntünün paylaşılmasından söz eder; bu da hem iyi hem kötü günlerde yanında olmakla uyumludur.'),
  ('"İyi bir okur, okuduklarını ... ; böylece metinle arasında bir bağ kurar." cümlesinde boşluğa hangisi getirilmelidir?', 'kendi yaşantısıyla ilişkilendirir', ['hızla okuyup unutur', 'yalnızca ezberler', 'hiç sorgulamadan, olduğu gibi kabul eder'], 'Metinle bağ kurmak, okunanı kişinin kendi deneyimleriyle ilişkilendirmesiyle olur.'),
  ('"Büyük şehirlerde insanlar kalabalığın içinde yalnızdır." cümlesinden hangisi çıkarılabilir?', 'Fiziksel yakınlık, duygusal yakınlık anlamına gelmez.', ['Büyük şehirlerde hiç insan yoktur.', 'Kalabalık yerler insanı mutlu eder.', 'Küçük kasabalarda yaşayan herkes büyük şehirlilerden daha yalnızdır.'], 'Kalabalıkta yalnız olmak, insanlar yan yana olsa da aralarında gönül bağı kurulmadığını anlatır.'),
  ('"Bakmak" eylemi aşağıdakilerin hangisinde "birinin bakımını üstlenmek" anlamında kullanılmıştır?', 'Ablası, annesi hastalanınca küçük kardeşlerine baktı.', ['Pencereden dışarı baktı, kar yağıyordu.', 'Doktor hastanın raporuna baktı.', 'Evin önü denize bakıyordu.'], 'Kardeşlere bakmak, onların bakımını, gözetimini üstlenmektir. Diğerlerinde görmek, incelemek ve yönelmek anlamları vardır.'),
  ('"Vermek" sözcüğü aşağıdaki cümlelerin hangisinde "bir karara varmak" anlamında kullanılmıştır?', 'Uzun tartışmalardan sonra taşınmaya karar verdik.', ['Arkadaşına doğum günü için bir kitap verdi.', 'Bu ağaç her yıl bol meyve verir.', 'Konser, salondakilere büyük bir coşku verdi.'], '"Karar vermek" kalıbında eylem, bir yargıya varmayı anlatır; diğerlerinde armağan etmek, ürün oluşturmak ve duygu uyandırmak anlamları vardır.'),
  ('"Atmak" sözcüğü aşağıdaki cümlelerin hangisinde "gerçek olmayan bir şeyi söylemek" anlamındadır?', 'Ona inanma, yine atıyor; o gün orada değildi.', ['Topu kaleye doğru var gücüyle attı.', 'Çöpleri sabah kapının önüne attı.', 'Mektubu postaya attıktan sonra eve döndü.'], 'Halk dilinde "atmak", yalan söylemek, uydurmak anlamına da gelir; cümlenin devamı bu anlamı doğrular.'),
  ('"İşlemek" sözcüğü aşağıdaki cümlelerin hangisinde "bir konuyu ele alıp geliştirmek" anlamındadır?', 'Yazar, romanında göç konusunu ustaca işlemiş.', ['Annem, örtünün kenarına çiçek işledi.', 'Yağmur suyu duvarın içine işlemiş.', 'Bu saatte otobüsler daha seyrek işliyor.'], 'Bir konuyu işlemek, onu ayrıntılı biçimde ele almak demektir. Diğerlerinde nakış yapmak, sızmak ve sefer yapmak anlamları vardır.'),
  ('"El" sözcüğü aşağıdaki cümlelerin hangisinde "yabancı, başkası" anlamında kullanılmıştır?', 'El oğluna güvenme, önce kendi işine bak.', ['Elini yıkamadan yemeğe oturma.', 'Kartlardan bir el daha oynayalım mı?', 'Babasının elinden tutup karşıya geçti.'], '"El oğlu" yabancı, başkası demektir. Diğerlerinde organ, oyun turu ve yine organ anlamları vardır.'),
  ('Aşağıdaki cümlelerin hangisinde "yaklaşık" sözcüğü, kesinlik bildiren bir sözle birlikte kullanıldığı için anlam bozukluğu oluşmuştur?', 'Toplantıya yaklaşık tam olarak elli kişi katıldı.', ['Toplantıya yaklaşık elli kişi katıldı.', 'Toplantıya tam elli kişi katıldı.', 'Toplantıya ellinin üzerinde kişi katıldı.'], '"Yaklaşık" kesin olmayan bir sayıyı, "tam olarak" ise kesin bir sayıyı bildirir; ikisi bir arada kullanılamaz.'),
  ('"Ödünç" sözcüğünün doğru kullanıldığı cümle hangisidir?', 'Kütüphaneden ödünç aldığım kitabı iki hafta içinde geri vermeliyim.', ['Bu kitabı ödünç aldım, artık sonsuza dek benim.', 'Ödünç verdiğim kalemi armağan olarak sakla.', 'Marketten ödünç ekmek aldım, parasını ödedim.'], '"Ödünç", geri verilmek üzere alınan ya da verilen demektir; geri verme zorunluluğu bu anlama uyar.'),
  ('"Kurt" yerine köylülerin "canavar" ya da "ağzı kara" demesi gibi kullanımlar hangi amaçla yapılır?', 'Korkulan bir varlığın adını doğrudan anmaktan kaçınmak için', ['Hayvanın boyutunu tam olarak belirtmek için', 'Hayvanı övmek ve sevdirmek için', 'Hayvanın bilimsel adını kullanmak için'], 'Korkulan varlığın adını anmamak için başka adlar kullanmak, güzel adlandırma (örtmece) eğiliminin bir örneğidir.'),
  ('Aşağıdaki cümlelerin hangisinde hoşa gitmeyen bir durum daha yumuşak bir sözle anlatılmıştır?', 'Dedem artık biraz ağır işitiyor.', ['Dedem her sabah gazete okur.', 'Dedem bahçede domates yetiştiriyor.', 'Dedem bize eski bayramları anlattı.'], '"Sağır" demek yerine "ağır işitmek" demek, hoş olmayan bir durumu yumuşatarak anlatmaktır.'),
  ('"Rüzgâr ağaçların arasında uğulduyor, dallar çatırdıyordu." cümlesindeki yansıma sözcüklerle ilgili hangisi doğrudur?', 'İkisi de doğadaki seslerin taklidinden türemiştir.', ['İkisi de bir duyguyu anlatan soyut adlardır.', 'İkisi de yabancı dillerden geçmiştir.', 'Yalnızca biri ses yansımasıdır, öteki renk bildirir.'], '"Uğuldamak" ve "çatırdamak", doğadaki seslerin yansımasından türemiş eylemlerdir.'),
  ('"Acı bir haber aldık." cümlesinde "acı" sözcüğünün kullanımı için hangisi doğrudur?', 'Tat bildiren bir sözcük, bir haberi nitelemek için kullanılmıştır.', ['Sözcük, yemeğin tadını anlatır.', 'Sözcük, bir sesin yansımasıdır.', 'Sözcük, gerçek anlamda bir bitkinin adıdır.'], '"Acı" tat duyusuna ait bir sıfattır; habere aktarılarak "üzücü" anlamı kazanmıştır.'),
  ('"Abayı yakmak" deyimi hangi anlamda kullanılır?', 'Birine gönül vermek, âşık olmak', ['Bir giysiyi ütülerken yakmak', 'Çok öfkelenmek', 'Bir işten vazgeçmek'], '"Abayı yakmak", birine tutulmak, âşık olmak anlamına gelen bir deyimdir.'),
  ('"Hesapta olmayan misafirler gelince annem ... ; ne pişireceğini bilemedi." cümlesinde boşluğa hangi deyim getirilmelidir?', 'eli ayağına dolaştı', ['gözü doydu', 'başı göğe erdi', 'eli ayağı tuttu'], '"Eli ayağına dolaşmak", telaştan ne yapacağını şaşırmak demektir; cümlenin devamı bu anlamı destekler.'),
  ('"Başı göğe ermek" deyimi aşağıdaki durumların hangisinde kullanılabilir?', 'Yıllarca beklediği torununun doğduğunu öğrenen dede için', ['Uçağa ilk kez binen bir yolcu için', 'Uzun boylu bir basketbolcu için', 'Dağın zirvesine tırmanan bir dağcı için'], 'Deyim, çok sevinmek, büyük bir mutluluğa erişmek anlamındadır.'),
  ('"Su testisi su yolunda kırılır." atasözü aşağıdaki durumlardan hangisine uygundur?', 'Yıllarca dağcılık yapan birinin bir tırmanışta kaza geçirmesi', ['Hiç yüzme bilmeyen birinin denize girmemesi', 'Testisini dikkatle taşıyan bir çocuğun övülmesi', 'Su tasarrufu yapan bir ailenin faturasının düşmesi'], 'Atasözü, bir işi sürekli yapanın er geç o işte zarar görebileceğini anlatır.'),
  ('"Dünyada hiç ağaç olmasaydı nefes alacak temiz havamız da olmazdı." cümlesinde hangi anlatım vardır?', 'Gerçekleşmemiş bir durumun sonucunu düşünme', ['Geleceğe yönelik, uygulanması istenen bir öneri', 'Gerçekleşmiş bir olayın anlatımı', 'Bir kavramın sözlük tanımı'], '"Olmasaydı ... olmazdı" yapısı, gerçekte olmayan bir durumu varsayarak sonucunu ortaya koyar.'),
  ('Aşağıdakilerin hangisi yanıt beklemeyen, bir yargıyı pekiştiren bir soru cümlesidir?', 'Annesinin ellerinden öpmeyen evlat olur mu?', ['Annen bu akşam eve kaçta gelecek?', 'Hangi kitabı okumak istersin?', 'Kütüphaneye nasıl gidebilirim?'], 'İlk soru, "her evlat annesinin elini öper" yargısını pekiştirmek için sorulmuştur; diğerleri bilgi almaya yöneliktir.'),
  ('"Seninle konuşmamak için bir nedenim yok." cümlesinden hangisi anlaşılır?', 'Konuşan, karşısındakiyle konuşmakta bir sakınca görmemektedir.', ['Konuşan, karşısındakiyle hiç konuşmak istememektedir.', 'Konuşan, karşısındakine çok kızgındır ve onunla görüşmek istemez.', 'Konuşan, karşısındakini tanımamaktadır.'], '"Konuşmamak için nedenim yok" demek, konuşmaya engel bir durum olmadığını, yani konuşabileceğini anlatır.'),
  ('"Çekim" sözcüğü aşağıdakilerin hangisinde fizik terimi olarak kullanılmıştır?', 'Ay\'ın çekim kuvveti, denizlerde gelgit olayına yol açar.', ['Filmin çekimleri bir köyde yapıldı.', 'Bu şarkıcının sahnedeki çekimi çok güçlü.', 'Fiilin geçmiş zaman çekimini tahtaya yazdı.'], 'Fizikte çekim, kütleler arasındaki çekim kuvvetini anlatır. "Fiil çekimi" ise dil bilgisi terimidir ama soru fiziği sormaktadır.'),
  ('"Hücre" sözcüğü hangi cümlede biyoloji terimi olarak kullanılmıştır?', 'Canlıların yapısındaki en küçük birim hücredir.', ['Mahkûm, dar bir hücrede yıllarca kaldı.', 'Arı peteğinin her hücresi bal doluydu.', 'Gizli örgütün hücreleri tek tek çökertildi.'], 'Biyolojide hücre, canlıların yapı ve görev birimidir; diğerlerinde oda, bölme ve küçük örgüt birimi anlamları vardır.'),
  ('"Ekmek" sözcüğünün aşağıdakilerin hangisinde ötekilerden farklı olarak bir eylem bildirdiği görülür?', 'Çiftçiler bu yıl tarlaya buğday ekmek için yağmuru bekliyor.', ['Fırından taze ekmek aldık.', 'Kahvaltıda ekmeğe bal sürdük.', 'Bayat ekmekleri kuşlara verdik.'], 'Tarlaya buğday ekmek, toprağa tohum atmak eylemidir; yiyecek adı olan "ekmek" ile sesteştir.'),
  ('"Taşıt" sözcüğüne göre en özel anlamlı olan hangisidir?', 'minibüs', ['araç', 'kara taşıtı', 'deniz taşıtı'], 'Minibüs belirli bir taşıt türüdür; diğer seçenekler daha geniş kapsamlı kavramlardır.'),
  ('"Çalgı - telli çalgı - bağlama" sıralamasıyla ilgili hangisi doğrudur?', 'Kavramlar genelden özele doğru sıralanmıştır.', ['Kavramlar özelden genele doğru sıralanmıştır.', 'Üç sözcük de eş anlamlıdır.', 'Sözcükler arasında karşıtlık vardır.'], 'Çalgı en geniş kavramdır; telli çalgı onun bir türü, bağlama da telli çalgıların bir örneğidir.'),
  ('Aşağıdaki cümlelerden hangisi ötekilerden farklı olarak bir rica bildirir?', 'Müsaitsen bu kolileri taşımama yardım eder misin?', ['Bu kolileri hemen taşı!', 'Kolileri taşımazsan sonra görürsün.', 'Koliler taşınırken dikkatli olun, kırılabilir.'], 'Nazik bir soru biçiminde yardım istenmesi ricadır; diğerleri emir, tehdit ve uyarıdır.'),
  ('"Vay be, bu kadar küçük bir çocuk bu kadar güzel nasıl çizebilir!" cümlesinde hangi duygu vardır?', 'Hayranlıkla karışık şaşkınlık', ['Öfke ve kızgınlık', 'Pişmanlık', 'Korku'], '"Vay be" ünlemi ve ünlem cümlesi, çocuğun çizimine duyulan hayranlığı ve şaşkınlığı anlatır.'),
  ('Annesi Ali\'ye "Akşam yemeğinden önce ödevini bitir." dedi. Bu söz dolaylı anlatımla nasıl aktarılır?', 'Annesi Ali\'ye akşam yemeğinden önce ödevini bitirmesini söyledi.', ['Annesi Ali\'ye: "Akşam yemeğinden önce ödevini bitir." dedi.', 'Ali, akşam yemeğinden önce ödevini bitirdi.', 'Annesi, Ali\'nin ödevini bitirdiğini öğrendi.'], 'Dolaylı anlatımda emir, "-masını söyledi" yapısıyla aktarıcının cümlesine katılır.'),
  ('"Komşumuz, kızının sınavı kazandığını sevinçle haber verdi." cümlesi doğrudan anlatıma çevrilirse hangisi elde edilir?', 'Komşumuz sevinçle "Kızım sınavı kazandı." dedi.', ['Komşumuz, kızının sınavı kazanacağını umuyordu.', 'Komşumuzun kızı sınavı kazanamadı.', 'Komşumuz, kızının sınava gireceğini söyledi.'], 'Doğrudan anlatımda söz, söyleyenin ağzından, tırnak içinde ve değiştirilmeden verilir.'),
  ('"Kitabın son bölümünü dün gece okudum." cümlesinde vurgulanan öğe, yükleme yöneltilen hangi soruya yanıt verir?', 'Ne zaman?', ['Neyi?', 'Kim?', 'Nerede ve kiminle?'], 'Vurgu yüklemden hemen önceki öğeye düşer; burada "dün gece" zaman bildirir ve "ne zaman?" sorusunu karşılar.'),
  ('"Eli uzun" sözü bir kişi için kullanıldığında hangi anlam kastedilir?', 'Hırsızlık yapan biri olduğu', ['Kolları uzun biri olduğu', 'Cömert biri olduğu', 'Becerikli bir zanaatkâr olduğu'], '"Eli uzun", başkasının malına el uzatan, hırsızlık yapan kişi anlamında kinayeli bir sözdür.'),
  ('"Romandaki olaylar inandırıcı değil; kahramanlar en zor durumlardan bile mucize eseri kurtuluyor." yargısının türü nedir?', 'Gerekçeli olumsuz eleştiri', ['Gerekçesiz bir övgü', 'Kesin, ölçülebilir bir bilgi', 'Yazara yönelik bir teşekkür'], 'Olayların inandırıcı olmadığı söylenmiş ve bunun gerekçesi (mucize kurtuluşlar) verilmiştir.'),
  ('"Bu otobüs her sabah geç geliyor, işe her gün yetişemiyoruz." ve "Bu sabah otobüs biraz geç geldi." cümleleri arasındaki fark nedir?', 'İlki yakınma içerir, ikincisi yalnızca bir durumu bildirir.', ['İkisi de birer yakınmadır.', 'İlki bir durumu bildirir, ikincisi yakınma içerir.', 'İkisi de bir öneri bildirir.'], 'İlk cümlede sürekli yaşanan bir sıkıntıdan şikâyet edilir; ikinci cümle tek seferlik bir olayı aktarır.'),
  ('"Bu dağ köyünde zaman, şehirdekinin aksine ağır ağır akar." cümlesinde yapılan karşılaştırmayla ilgili hangisi doğrudur?', 'Köydeki ve şehirdeki yaşam temposu kıyaslanmıştır.', ['Köyün ve şehrin nüfusu karşılaştırılmıştır.', 'Köy ile şehir arasındaki uzaklık ölçülmüştür.', 'İki şehir birbirine benzetilmiştir.'], '"Zamanın ağır akması", yaşamın yavaş temposunu anlatır; köy bu yönden şehirle karşılaştırılmıştır.'),
  ('"Bu kumaş, ötekine göre daha pahalı olsa da daha uzun ömürlü." cümlesinden hangisi çıkarılabilir?', 'Öteki kumaş daha ucuz ama daha kısa ömürlüdür.', ['İki kumaşın fiyatı aynıdır.', 'Pahalı kumaş daha çabuk eskir.', 'Öteki kumaş hem pahalı hem de dayanıklıdır.'], 'Bir kumaş fiyat ve ömür bakımından ötekiyle kıyaslanmıştır; bundan öteki kumaşın daha ucuz ve kısa ömürlü olduğu sonucu çıkar.'),
  ('"Yazar, bu kitabında öncekilere oranla çok daha sade bir dil kullanmış." cümlesinden hangisi kesin olarak çıkarılabilir?', 'Yazarın önceki kitaplarının dili bu kitaba göre daha az sadedir.', ['Yazarın önceki kitapları hiç okunmamıştır.', 'Yazarın bu kitabı en çok satan kitabıdır.', 'Yazar artık şiir yazmaktadır.'], 'Karşılaştırma, önceki kitapların dilinin bu kitaba göre daha az sade olduğunu gösterir; diğer yargılar cümlede yoktur.'),
  ('"Kar yağışı başlar başlamaz belediye yollara tuz döktü." cümlesinde "başlar başlamaz" sözü hangi anlamı katmıştır?', 'Bir eylemin ardından hemen öteki eylemin yapıldığı', ['Bir eylemin hiç yapılmadığı', 'İki eylemin birbirinden çok uzun aralıkla yapıldığı', 'Bir eylemin amacının belirtildiği'], '"-ar -maz" yapısı, bir eylemin gerçekleşmesinin hemen ardından ötekinin yapıldığını anlatır.'),
  ('"Kendine inanmadıkça kimse sana inanmaz." cümlesinde başkalarının inanması neye bağlanmıştır?', 'Kişinin önce kendine inanmasına', ['Kişinin başkalarına inanmasına', 'Kişinin çok konuşmasına', 'Kişinin başarılı bir geçmişi olmasına'], '"-madıkça" yapısı koşul bildirir; başkalarının inanması, kişinin kendine inanması koşuluna bağlanmıştır.'),
  ('"Her şey olacağına varır." sözüyle anlamca en yakın cümle hangisidir?', 'Olacak olan bir şekilde gerçekleşir.', ['Her şeyi biz belirleriz.', 'Hiçbir şey değişmez.', 'Geçmişte olanlar unutulmalıdır.'], 'Söz, olayların kendi akışı içinde olması gereken sonuca ulaşacağını anlatır.'),
  ('"Bu kadar kalabalık bir sınıfta öğretmen her öğrenciyle tek tek ilgilenemez; ne var ki bizim öğretmenimiz bunu başarıyor." cümlesinden hangisi çıkarılabilir?', 'Öğretmen, beklenenin ötesinde bir çaba göstermektedir.', ['Sınıf çok az öğrenciden oluşmaktadır.', 'Öğretmen hiçbir öğrenciyle ilgilenmemektedir.', 'Kalabalık sınıflarda eğitim daha kolaydır.'], '"Ne var ki" ile genel beklentinin tersine bir durum anlatılır: öğretmen kalabalığa rağmen herkesle ilgilenir.'),
  ('Önceleri yalnızca kâğıtlardan oluşan belge topluluklarını anlatan "dosya" sözcüğünün bugün bilgisayarda saklanan kayıtları da anlatması hangi anlam olayına örnektir?', 'Anlam genişlemesi', ['Anlam daralması', 'Sesteşlik', 'Güzel adlandırma yoluyla örtmece'], 'Sözcük eski anlamını korurken yeni bir varlığı da karşılamaya başlamıştır; kapsamı büyüdüğü için bu anlam genişlemesidir.'),
  ('"Fare" sözcüğünün bir hayvan adıyken bilgisayarla çalışırken kullanılan donanımı da anlatır olması nasıl açıklanır?', 'Benzerlik yoluyla anlamın genişlemesiyle', ['Anlamın daralmasıyla', 'Sözcüğün dilden düşmesiyle', 'Karşıt anlam kazanmasıyla'], 'Biçim benzerliği nedeniyle sözcük yeni bir nesneyi de karşılamaya başlamış, anlamı genişlemiştir.'),
  ('"Pek", "çok", "daha", "en" gibi sözcüklerin cümledeki ortak işlevi hangisidir?', 'Niteliklerin derecesini belirlemek', ['Cümleleri birbirine bağlamak', 'Bir eylemin zamanını göstermek', 'Bir varlığın adını bildirmek'], 'Bu sözcükler sıfat ve zarfların önüne gelerek onların derecesini belirtir.'),
  ('"Yeşil Bursa", "Başkent", "Ege\'nin incisi" söz öbeklerinin ortak özelliği nedir?', 'Bir yeri adıyla değil, öne çıkan bir niteliğiyle anmaları', ['Her birinin bir bölgenin bilimsel adı olması', 'Bir yerin nüfusunu bildirmeleri', 'Ad aktarması yoluyla birer kişiyi anlatmaları'], 'Bu söz öbekleri, yerleri doğrudan adlarıyla değil, onlara özgü bir özellikle dolaylı biçimde anlatır; bu dolaylamadır.'),
  ('"Yüce Önder" ifadesi bir kişiyi adını kullanmadan anmak için kullanıldığında hangi anlatım yolu söz konusudur?', 'Dolaylama', ['Kişileştirme', 'Duyular arası aktarma', 'Abartma'], 'Bir kişiyi adı yerine onu niteleyen bir sözle anmak dolaylamadır.'),
  ('"Dertlerimi anlatsam bitmez; ama kime anlatayım, kimse dinlemiyor ki." cümlesinde hangi iki duygu bir arada bulunur?', 'Yakınma ve yalnızlık', ['Umut ve sevinç', 'Övünç ve gurur', 'Öfke ve tehdit'], 'Dertlerinin çok olmasından yakınan kişi, onu dinleyen kimse olmadığını söyleyerek yalnızlığını da dile getirir.'),
  ('"Dedem, gençken bu köyde yalnızca üç ev olduğunu anlatırdı." cümlesindeki anlatımla ilgili hangisi doğrudur?', 'Başkasından duyulan bir bilgi, aktaranın cümlesiyle verilmiştir.', ['Dedenin sözleri hiç değiştirilmeden tırnak içinde aktarılmıştır.', 'Konuşan, köyün geçmişini kendi gözüyle görmüştür.', 'Cümlede bir öneri ve tavsiye yer almaktadır.'], 'Dedenin anlattıkları tırnak kullanılmadan, aktaranın kendi cümlesine katılarak verilmiştir; bu dolaylı anlatımdır.'),
  ('"Ağaç - meyve ağacı - elma ağacı - Amasya elması ağacı" sıralamasında her sözcük grubu bir öncekine göre nasıldır?', 'Daha özeldir.', ['Daha geneldir.', 'Eş anlamlıdır.', 'Karşıt anlamlıdır.'], 'Her basamakta kapsam daralır; meyve ağacı ağaçların, elma ağacı meyve ağaçlarının bir türüdür.'),
  ('"Bu sabah hiç kahvaltı yapmadım ama karnım çok tok, çünkü az önce doyasıya kahvaltı ettim." cümlesindeki sorun nedir?', 'Birbirini yok eden yargılar bir arada kullanılmıştır.', ['Cümlede yüklem bulunmamaktadır.', 'Cümlede karşılaştırma yapılmıştır.', 'Cümle soru anlamı taşımaktadır.'], '"Hiç kahvaltı yapmadım" ile "doyasıya kahvaltı ettim" yargıları birbiriyle çelişir.'),
  ('"Bu takımın taraftarları hep kavgacıdır, onlarla aynı tribünde oturulmaz." cümlesi neden ön yargılı bir tutum içerir?', 'Bir topluluğun tüm bireylerine tek bir olumsuz özellik yüklendiği için', ['Bir maçın sonucu nesnel olarak aktarıldığı için', 'Taraftarların sayısı verildiği için', 'Tribünün yeri tarif edildiği için'], '"Hep" sözüyle bütün taraftarlar, tanınmadan aynı olumsuz özellikle nitelenmiştir; bu bir genelleme ve ön yargıdır.'),
  ('"Kaşla göz arasında" deyimi aşağıdaki cümlelerin hangisinde anlamına uygun kullanılmıştır?', 'Kaşla göz arasında cüzdanımı çalıp kaçtılar.', ['Kaşla göz arasında saatlerce bekledik.', 'Kaşla göz arasında yıllar süren bir yolculuk yaptık.', 'Kaşla göz arasında ağır ağır yürüdü.'], 'Deyim "çok kısa bir sürede, kimse fark etmeden" anlamındadır; saatler, yıllar ve ağır ağır yürümek bu anlamla çelişir.'),
  ('"Yangından mal kaçırır gibi" deyimi hangi davranışı anlatır?', 'Bir işi büyük bir telaş ve acele içinde yapmayı', ['Bir işi çok sakin ve düzenli yapmayı', 'Başkasının malını korumayı', 'Yangını söndürmeye çalışmayı'], 'Deyim, gereksiz bir acele ve telaşla davranmayı anlatır.'),
  ('"Bir taşla iki kuş vurmak" deyimi aşağıdaki durumların hangisine uygundur?', 'İşe bisikletle giderek hem spor yapan hem de yol parası biriktiren Ece', ['Sınavda iki soruyu boş bırakan Ali', 'Avlanmaya giden ama eli boş dönen Murat', 'İki işi birden yapmaya çalışırken ikisini de bitiremeyen Can'], 'Deyim, tek bir girişimle iki ayrı yarar sağlamayı anlatır; Ece bisikletle hem spor yapmış hem para biriktirmiştir.'),
  ('"Kuru" sözcüğü aşağıdakilerin hangisinde "boş, anlamsız, yararsız" anlamında kullanılmıştır?', 'Kuru vaatlerle seçmenleri kandıramazsınız.', ['Çamaşırlar güneşte çabucak kurudu.', 'Kuru dalları toplayıp ateş yaktık.', 'Kuru incir kışın çok yenir.'], '"Kuru vaat", içi boş, yerine getirilmeyecek söz anlamında mecazdır.'),
];
